INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-outforce', 1167, '2000-09-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2si5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/k4veb3oe8kqv9h4fefal.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Outforce', 'The Outforce is a real-time strategy game set in the depths of space. There are three races from which to choose, and more than 120 different units available, including tow ships, phasing units, and self-destructing units. The 3-D environment features a free-floating camera with a variable zoom field. The game''s artificial intelligence has a genetic learning algorithm, and the physics system includes pressure waves, elastic collisions, gravity, and push-and-pull force. Up to eight players can battle it out over the Internet or on a LAN.' FROM games WHERE igdb_id = 1167 ON CONFLICT (game_id, language_code) DO NOTHING;
