INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-grid--1', 185943, '2000-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4b03.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scf3cb.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Grid', 'The Grid is a 2000 arcade game by Midway. It is a third person shooter which consists of a super-violent television game show hosted by a Smash TV-like host. The game centres around deathmatches. Players control their character using a joystick with a trigger for shooting, a top button for jumping and trackball for aiming. The object of each match is to accumulate the most points by eliminating other opponents. Local multiplayer with up to six players is possible by linking up multiple cabinets. Computer-controlled bots can also be used in place of human opponents. Players can also collect cash that can be used to upgrade player attributes. Individual player progress and statistics can be saved and retrieved through unique account numbers that are entered on a keypad. The game was created by the developers behind the Mortal Kombat series of games and has cameos from characters Sub-Zero, Scorpion, and Noob Saibot. This was Midway''s last arcade game.' FROM games WHERE igdb_id = 185943 ON CONFLICT (game_id, language_code) DO NOTHING;
