INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kisou Jidaigeki Sugoroku: Shinobi No Roku', 'Kisou Jidaigeki Sugoroku - Shinobi No Roku is a curious board game in which the player controls a group of ninja characters that will advance through different board tables using different kind of objects and battle cards. To advance the game displays a battle screen when they encounter an enemy.' FROM games WHERE igdb_id = 377559 ON CONFLICT (game_id, language_code) DO NOTHING;
