INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('in-flight-tetris', 145631, '2000-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2xoz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar7v4.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'In-Flight Tetris', 'One of the most popular games in the world and bound to be an everlasting classic, Tetris is without a doubt one of the most challenging and addictive game available out there. Whether you''re a beginner or an advanced player, this game will provide you with hours of entertainment. Line up the falling pieces to form lines. When you run out of space, the game ends. Make Tetris combos to get more points. In-Flight Tetris is a Tetris game available to play in some passenger airplanes. It is currently sold to airlines by Global Eagle as part of their Airgames catalog. In-Flight Tetris uses standard Guideline rules for gameplay, and it uses either touch or built-in remote controls. Game interface is mostly based on Tetris Zone. There are four modes available: Marathon, Fourty Lines, Ultra, and Battle 2P. Scores are saved on a leaderboard.' FROM games WHERE igdb_id = 145631 ON CONFLICT (game_id, language_code) DO NOTHING;
