INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spirit of Speed 1937', 'Spirit of Speed 1937 is a racing video game developed by Broadsword Interactive and published by both Acclaim Entertainment for the Dreamcast and by Microprose for PC. The game was released in North America on June 29, 2000. Spirit of Speed 1937 allegedly takes gamers back to the 1930s when motorsports were in their infancy and drivers raced for the thrill of speed, the danger, and the glamor that came with it.' FROM games WHERE igdb_id = 16303 ON CONFLICT (game_id, language_code) DO NOTHING;
