INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ISS: International Superstar Soccer', 'International Superstar Soccer (abbreviated as ISS) is a football video game in the International Superstar Soccer series by Konami. Players can train and edit their teams, and they can change the formations and tactics before the match. During the match, they can adjust camera angles, make substitutions and tactical changes, adjust the game speed, and so on. The main game element is controlling the players, making searching passes, and scoring goals.' FROM games WHERE igdb_id = 136303 ON CONFLICT (game_id, language_code) DO NOTHING;
