INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deus Ex', 'A philosophical first-person WRPG set in a dystopian 2052 in which JC Denton, a nano-augmented agent for the anti-terrorist organization UNATCO, is tasked with stopping the invasion of Liberty Island by the terrorist group NSF. As events unfold, Denton finds that he plays a large part in a world-spanning conspiracy which forces him to ponder his allegiances, beliefs, morality, and view of right and wrong.' FROM games WHERE igdb_id = 41 ON CONFLICT (game_id, language_code) DO NOTHING;
