INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wizards & Warriors', 'Wizards & Warriors is a traditional party-based fantasy CRPG designed by David W. Bradley, the designer of the Wizardry series. Being a spiritual successor to that series, Wizards & Warriors plays similarly and incorporates many of the same themes, albeit cosmetically changed to set it outside the Wizardry fictional universe.' FROM games WHERE igdb_id = 80498 ON CONFLICT (game_id, language_code) DO NOTHING;
