INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Power Rangers: Lightspeed Rescue', 'The Windows/Mac version of Power Rangers Lightspeed Rescue was more like an activity center. The game uses interactive CD-ROMs called Datazords that provide a virtual interactive Power Rangers experience. Originally it was released on 6 CDs, bundled in complete with Power Rangers figure toys (one CD for each figure).' FROM games WHERE igdb_id = 275181 ON CONFLICT (game_id, language_code) DO NOTHING;
