INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Extreme Go-Kart Racing', 'This value-minded release comes to North America courtesy of Tommo and A1 Games. Play as one of 12 racers competing for first-place finishes on seven different race tracks, which include pavement and frozen landscapes. Three modes of play include: Grand Prix, Time Attack, and Two-Player Versus. Use the drift technique and grab turbo capsules littering the race courses to give you a competitive edge.' FROM games WHERE igdb_id = 45306 ON CONFLICT (game_id, language_code) DO NOTHING;
