INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('beatmania-featuring-dreams-come-true', 80674, '2000-05-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2cdc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8eb5.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beatmania Featuring: Dreams Come True', 'Beatmania Featuring: Dreams Come True is a rhythm game developed by Konami. It is the tenth game in the beatmania series and is part of the BEMANI franchise. The game is played with a controller with one turn table and 5 keys, three white and two black. On the screen you will see bars moving from the top to bottom in columns representing each of the keys and the turntable. When the bars reach the judgement line it is time to scratch. The only release in the series to be devoted to a single artist, the J-POP band Dreams Come True. Because of this, artist information is omitted from the song select screen. It is the only beatmania arcade version to feature song previews on the song select. A special mode called MONKeY LIVE is introduced, it acts as EXPERT mode in earlier mixes but has a small MONKeY LIVE section between songs which lets you earn back a bit of lost gauge. None of the songs have an ANOTHER chart. The entire song list is dedicated to Dreams Come True, which means the game has a total of 18 tracks. The smallest selection in the series since the original beatmania game.' FROM games WHERE igdb_id = 80674 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 80674 AND ge.slug = 'music' ON CONFLICT DO NOTHING;
