INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('turnabout', 44926, '2000-04-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4erh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scwteq.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Turnabout', 'While the old adage that "turnabout is fair play" applies in many situations, Natsume''s Turnabout is all about diabolical puzzles where players rotate the entire puzzle while the pieces move within its borders, sliding and rolling into mind-numbing configurations and patterns. The 100 puzzles provided are divided into two groups of 50: Begin Mode and Main Mode. The first 50 puzzles must be solved in order to open up the remaining 50, but the puzzles are numbered in five rows of ten each -- solving seven rounds in a row will open up the next row of ten, thus the puzzles needn''t be solved sequentially. Puzzle pieces in Turnabout come in three types: colored balls, colored blocks, and sliding blocks. By rotating the puzzle board, balls and sliding blocks adhere to the forces of gravity and fall down into open slots. Manipulating the puzzle correctly takes skill and usually no more than ten to fifteen "steps," even at advanced levels. Learning to solve puzzles backward by picturing the flow of the pieces mentally can be an essential tool to success and none of the 100 puzzle board configurations are the same shape. For players looking for even more challenges, up to 50 custom-made puzzles can be devised, using five different colored balls and blocks and nine movable sliders (blocks) in Edit Mode.' FROM games WHERE igdb_id = 44926 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 44926 AND ge.slug = 'puzzle' ON CONFLICT DO NOTHING;
