INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Golgo-13 2 - Kiseki no Dandou', 'A sequel to the 1999 Golgo-13 arcade lightgun game developed by Eighting/Raizing and published by Namco. The player once again plays as the titular assassin Duke Togo codenamed Golgo 13. The game takes the player on a series of assignments with different targets that need to be dispatched with a scoped rifle. The sequel adds a new set of assignments alongside a remix of various assignments from the previous game, all based on the manga series.' FROM games WHERE igdb_id = 91928 ON CONFLICT (game_id, language_code) DO NOTHING;
