INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Microsoft Golf 2001 Edition', 'Take your golfing game to seven different authentically recreated courses. With over a dozen different scoring modes, Zone and LAN multiplayer support, this game has plenty of options for you to play even if you''ve never laid hands on a golf club before. Full tutorial and quickstart options ease you into the game. Multiple swing methods and customizations keep the game catering to you, not the other way around.' FROM games WHERE igdb_id = 78392 ON CONFLICT (game_id, language_code) DO NOTHING;
