INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('solid-link-dungeon-side', 382624, '2000-11-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob43w.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4z4o.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Solid Link: Dungeon Side', 'Solid Link Dungeon Side is a classic first person RPG in which the player is a hero (male or female one) that arrives to the city of Grikodol. There he can recruit other 3 members to join his party and after that he can go explore the dungeon where the evil creatures live. The game features 8 different main characters for the player to choose his hero. The gameplay is in first person perspective and the player have to walk around the dungeon in the search of treasure and other passages to advance through there, during the battles the player can choose the attack that each of his characters will use (attack, magic, defend, etc) and which enemy he will attack. The battles appears really often and are really hard to survive the dangers. During the dungeon exploration the player can camp and refill his characters energy. During the battles the player gain money that he can use in the town to buy items, improve weapons (or buy new ones), armours, etc.' FROM games WHERE igdb_id = 382624 ON CONFLICT (game_id, language_code) DO NOTHING;
