INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Robin Lloyd no Bouken', 'The Adventures of Robin Lloyd is a detective adventure game mixed with some action RPG elements, set in 1926 London, You need to get the clues by talking to various people and interact with objects. The game''s main character private detective Robin Lloyd, must solve countless mysterious! A key element of this game is its investigation system that lets you study objects that rouse your suspicion by looking at them from below or behind and even turning them upside down at times.' FROM games WHERE igdb_id = 62988 ON CONFLICT (game_id, language_code) DO NOTHING;
