INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-operative-no-one-lives-forever', 897, '2000-11-09', 68, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8yzl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/komhvfwuvr2g0pnxgedb.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Operative: No One Lives Forever', 'No One Lives Forever is to be a fast-paced, story-driven first-person shooter that delivers over-the-top action, outrageous villains, and wry humor in the tradition of the great 1960''s Bond films. You play Cate Archer an undercover operative for MI-Zero. Your mission is to arrange for the defection of a prominent East German biophysicist that goes by the name of Otto Dentz. However things go wrong when a terrorist group known as the HARM abducts Dentz during a flight to England. Assume the role of Cate Archer, an operative working for UNITY, a secret organization fighting to free the world from the clutches of H.A.R.M.. From tense subterfuge to in-your-face combat, No One Lives Forever ups the ante with 1960''s-influenced spy action, vivid international locates, and deadly arch villains.' FROM games WHERE igdb_id = 897 ON CONFLICT (game_id, language_code) DO NOTHING;
