INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('monster-rancher-explorer', 49860, '2000-11-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/try5qydksrfyaouuy5r5.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster Rancher Explorer', 'The MONSTER RANCHER franchise returns with this thoroughly entertaining adventure for handheld gamers. Help the well-meaning Cox fight through 60 enormous, puzzle-filled levels, fending off certain monsters while allying yourself with others. Each level requires you to find a hidden key in order to advance to the next stage, a task that becomes increasingly difficult as things progress. Luckily, you''re not going at it alone. You can unlock such friendly beasts as Gali, Hare, Mocchi, Suezo, and Tiger in order to help you fend off all enemies. Each of the friendly monsters serves as a power-up of sorts, increasing your overall speed, granting you temporary invincibility, and more. Fans of the series know just how fun collecting and utilizing monsters can be, and the premise is at its absolute best in this GBA installment. Cool, anime-style graphics abound throughout the massive gaming experience, which allows you to play alone or square off against a fellow Rancher.' FROM games WHERE igdb_id = 49860 ON CONFLICT (game_id, language_code) DO NOTHING;
