INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-mask-of-zorro', 49965, '2000-02-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/x9yydfq3pm2c1zv0n1xc.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Mask of Zorro', 'The sly and evil Don Rafael Montero has devised a scheme to take control of California. The people need a hero, and that is when Zorro appears. You take the role of Zorro, using your sword and cunning to fight your way through 30 levels of action, exploring towns and mines and facing many treacherous enemies. Every wound you receive depletes Zorro''s life bar a little bit, but finding hearts or kissing Elena, Zorro''s beloved and Don Rafael''s daughter, will allow Zorro to regain his health. A soundtrack of Spanish guitar rhythms will make you think that you are in 1820s California. Guide Zorro as he tries to save the people of California from the rule of Don Rafael in THE MASK OF ZORRO.' FROM games WHERE igdb_id = 49965 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 49965 AND ge.slug = 'adventure' ON CONFLICT DO NOTHING;
