INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('top-gear-hyper-bike', 3615, '2000-03-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7b3r.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6dnb.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Top Gear Hyper-Bike', 'Motorbike racer set in the Top Gear series. The Championship mode has you alternating between dirt and street racing as you compete for points. You earn new bikes and courses along the way like many other games, but interesting twist is going from one kind of racing to the other. The physics of each type of racing are very different, and you''ll have to switch back and forth between dirt and racing tactics on the fly. The dirt bike racing is a lot more arcadey with all of the jumps and wide open tracks. You can earn turbo by pulling off tricks and there''s really nothing to stop you from testing your stunt skills while racing except your own nerve and imagination. In this way, Hyperbike is like Hydro Thunder where you''re expected to lean on that turbo button the whole time and it''s up to your racing skills to ensure there''s turbo available.' FROM games WHERE igdb_id = 3615 ON CONFLICT (game_id, language_code) DO NOTHING;
