INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Angel''s Present: A Marl Kingdom Story', 'Rhapsody III: Memories of Marl Kingdom is a role-playing video game developed and published by Nippon Ichi Software for the PlayStation 2. It is the third installment in the Rhapsody series. Unlike the previous games in the series, this game was only released once, although a special limited edition version of the game was released concurrently. Instead of the 2D graphics of the other Marl games, Memories of Marl Kingdom uses 3D backgrounds, but the character sprites themselves are kept 2D, much like many other Nippon Ichi games released afterwards.' FROM games WHERE igdb_id = 76591 ON CONFLICT (game_id, language_code) DO NOTHING;
