INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heroes Chronicles: Clash of the Dragons', 'Clash of the Dragons is the fourth part of Heroes Chronicles, following Masters of the Elements and preceding The World Tree. Tarnum takes up the bow and defends the Elves and Dwarves of AvLee as a Ranger while opposing the tyrannical Queen of Nighon, Mutare, and her legions of murderous Dragons.' FROM games WHERE igdb_id = 8435 ON CONFLICT (game_id, language_code) DO NOTHING;
