INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tennis-antics', 54426, '2000-12-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6q82.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3u6l.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tennis Antics', 'Tennis Antics is a mixture of tennis and wacky arcade action. Both players have a health bar similar to the ones used in fighting games. The objective of the game is not to score points to win games & sets, but to deplete the health bar of your opponent. This can be done in several ways:* First you can try to play the ball past your opponent. The higher the number of times the ball bounces on his side of the court before he returns it, the more damage is done to his health bar. You can also collect & use power-ups that turn the ball into a bomb or a plasma weapon to hurt your opponent. Other power-ups available include ones that temporarily increase your running speed, give you the ability to steal a power-up from your opponent or give you a shield. Finally, if you hold down the swipe button long enough your character will launch a special attack at the other side of the court. However, while you''re building up this attack you can''t hit the ball. Players can refill their health bar by eating fruit & candy that appears on the court during gameplay. The first player to win the required number of rounds (1, 3, 5 or 7) wins the match. In the single-player story-mode you start with only one character and collect 19 other characters by beating them in the 3 available episodes. Unlocked characters can then be used in exhibition games. The 3 episodes take place on a pirate-themed galleon court, a horror-themed graveyard court and a Christmas-themed wonderland court.' FROM games WHERE igdb_id = 54426 ON CONFLICT (game_id, language_code) DO NOTHING;
