INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vampire: The Masquerade - Redemption', 'Vampire: The Masquerade – Redemption is a 2000 role-playing video game based on White Wolf''s game Vampire: The Masquerade and follows the adventures of Christof Romuald, a 12th-century French crusader who is killed and subsequently revived as a Vampire. The game depicts Christof''s centuries-long journey from the Dark Ages of 12th century Prague and Vienna to modern-day London and New York City in search of his humanity and his kidnapped love, the nun Anezka.' FROM games WHERE igdb_id = 12 ON CONFLICT (game_id, language_code) DO NOTHING;
