INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('links-2001', 770, '2000-10-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8hzk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6cmq.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Links 2001', 'The venerable golf simulation from Access (nee Microsoft) returns. New features in this updated version include new graphics and ball physics, new courses and tour players, centimeter accurate greens, custom club distances; faster, easier online play and golfers that each have their own personalities. Included in the game are some of your favourite golfing heros, Arnold Palmer, Sergio Garcia and Annika Sörenstam to mention a few. Play as them or against them. There are six world-class courses featured in the game, San Diego''s Aviara, Canada''s Chateau Whistler, The Prince Course on Kauai, Hawaii; Westfields Golf Club, St Andrews Old Course and Mesa Roja fantasy course. More courses can be downloaded for free from the Web. Also included in the game is the Arnold Palmer Course Designer. Build your dream course, from the tee to the fairway to the hole.' FROM games WHERE igdb_id = 770 ON CONFLICT (game_id, language_code) DO NOTHING;
