INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('world-series-baseball-2k1', 45849, '2000-08-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co45rq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scijh9.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Series Baseball 2K1', 'World Series Baseball 2K1 is a sports video game developed by Wow Entertainment and published by Sega for the Dreamcast. It was the first game in the modern series to be featured on the Dreamcast, and was the spiritual successor to World Series Baseball for the Sega Genesis.[citation needed] It was released in July 2000 to coincide with the 2000 Major League Baseball All-Star Game in Atlanta.[citation needed] World Series Baseball 2K1 featured a cutting-edge graphical presentation adapted from the NAOMI game Super Major League, and its visuals were well ahead of any other baseball game at the time. Unfortunately, a lack of features, shoddy audio presentation, and major gameplay flaws meant that WSB2K1 was not well received by critics despite its fantastic graphics. The game is notorious for its sometimes-unresponsive controls, as well as the fact that manual fielding—a staple of baseball games for a half-decade prior to WSB2K1''s release—isn''t even an option available to players.[citation needed] After the debacle that was World Series Baseball 2K1, Sega decided to bring Visual Concepts (the developer behind the Dreamcast''s far more successful NBA 2K and NFL 2K series) in for the next version of the game. The result was World Series Baseball 2K2, a game that was considered a major improvement over WSB2K1.' FROM games WHERE igdb_id = 45849 ON CONFLICT (game_id, language_code) DO NOTHING;
