INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tnn-outdoors-fishing-champ', 49994, '2000-01-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/w576kfwgswal2zglikez.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TNN Outdoors Fishing Champ', 'Get out the rod and reel, because the challenge of fishing can now be put into the palm of your hand thanks to TNN OUTDOORS FISHING CHAMP. Play in the Free Fishing mode to get a feel for the game controls and learn how to reel-in the big one. When you want to test your mettle, try to become the undisputed fishing champion in the Tournament mode. You will have to travel to six different tournaments and catch a predetermined number of a specific kind of fish to stay alive in each. If your friends are fishing fanatics, you can challenge them and see who can catch the most fish in an hour. In all of the modes, there are over 30 different varieties of fish to catch including bluegill, catfish, walleye, rainbow trout, lake trout, and largemouth bass. Play TNN OUTDOORS FISHING CHAMP and have a fish tale to tell your friends.' FROM games WHERE igdb_id = 49994 ON CONFLICT (game_id, language_code) DO NOTHING;
