INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('roland-garros-french-open', 50071, '2000-06-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6l9n.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Roland Garros French Open', 'Roland Garros French Open is the only appearance of the franchise on the Game Boy Color. Less of a serious simulation of tennis than other versions, the handheld edition features cartoony 2D graphics and outrageous court locations. All-in-all, the game includes eight different players and twelve different tournaments. Only five players and four tournaments can be selected from the start, the others are unlocked by winning events. The starting tournaments are realistic grand slam events: the Roland Garros French Open (the only one with a license), the English Open (i.e. Wimbledon), the US Championship and the Australian Cup, on clay, grass or turf. Winning them unlocks the more unusual locations: from street and beach tournaments to far-out events in the Antarctic or on the moon. All events are single elimination, starting at the quarter finals. Matches follow original rules, and are seen from a standard perspective behind the controlled player. All characters (players, officials and fans) are drawn in a cartoony style with oversized heads. The controls allow for a variety of moves including backhand and forehand shots, volleys and lobs.' FROM games WHERE igdb_id = 50071 ON CONFLICT (game_id, language_code) DO NOTHING;
