INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mario-artist-talent-studio', 44059, '2000-03-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co21qs.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scesfk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Artist: Talent Studio', 'In Mario Artist: Talent Studio, the player can create their own characters in 3D, customizing features such as hair, skin, and eye color, voice, clothes, facial features, and body size and type. The process is similar to Nintendo''s later Miis, but much more detailed. The characters can then be inserted into movies and animations. Events during these movies can be controlled by pressing the Z-trigger. Images from external video can be imported using the Capture Cartridge.' FROM games WHERE igdb_id = 44059 ON CONFLICT (game_id, language_code) DO NOTHING;
