INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Banjo-Tooie', 'Grunty returns—and that''s bad news for Banjo and Kazooie! In this all-new adventure, combine everything you learned in the award-winning prequel, Banjo-Kazooie, with dozens of brand-new moves and abilities. Explore eight original worlds-like a monstrous factory and a dilapidated amusement park. Solve incredible puzzles that link those worlds together—sometimes you''ll have to complete tasks in several worlds to solve a single puzzle!' FROM games WHERE igdb_id = 3418 ON CONFLICT (game_id, language_code) DO NOTHING;
