INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'J.League Jikkyou Winning Eleven 2000 2nd', 'J.League Winning Eleven 2000 is the officially licensed action soccer game based on the second stage of the 1998 J.League season. It is the follow-up to J.league ''98-99. The series is well known for its smooth gameplay and simplicity of controls. J.League Winning Eleven 2000 2nd features the updated teams of the season 2000-2001.' FROM games WHERE igdb_id = 181571 ON CONFLICT (game_id, language_code) DO NOTHING;
