INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ninja Assault', 'Ninja Assault is an arcade game developed and released by Namco in 2000. Two years later it was also published as a PlayStation 2 exclusive title with GunCon 2 compatibility. Ninja Assault was developed by Namco, who also created the Time Crisis series. However, this game has more in common with Lethal Enforcers, Virtua Cop, and The House of the Dead series, whereby the movement is completely "on-rails" (i.e., with no hiding pedal), and the player must shoot away from the screen to reload. Both versions of this game support up to two players in cooperative gameplay.' FROM games WHERE igdb_id = 13901 ON CONFLICT (game_id, language_code) DO NOTHING;
