INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marvel vs. Capcom 2: New Age of Heroes', 'Marvel vs. Capcom 2: New Age of Heroes is the fourth game in the Marvel vs. Capcom series of fighting games. The player''s controls were simplified to make the gameplay more accessible to the wider audience of casual players and the button configuration was trimmed down to 4 main buttons and 2 assist buttons. The game also features a different air-combo system and 3 on 3 tag, compared to the 2 on 2 tag from previous games in the series.' FROM games WHERE igdb_id = 8247 ON CONFLICT (game_id, language_code) DO NOTHING;
