INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stay.: Fragments of Memories', 'Doujin game inspired by ONE ~Kagayaku Kisetsu e~. Contains three separate stories with three different protagonists: "Stay.": Nagamori Mizuka tries to cope with Kouhei''s sudden disappearance. "Before it turns into a memory": Kawana Misaki tries to find out what happened to Orihara Kouhei, with the help of Kouzuki Mio and Miyama Yukimi. "Sweet": Orihara Kouhei and Satomura Akane enjoy their daily life as boyfriend and girlfriend.' FROM games WHERE igdb_id = 308972 ON CONFLICT (game_id, language_code) DO NOTHING;
