INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kawaii Pet Shop Monogatari 2', 'Similar to its predecessor, this is an animal-raising RPG adding more animals and improvements. The protagonist''s father, who runs a pet shop, goes missing after a shipwreck. The protagonist takes over the pet shop management and embarks on an adventure with her exceptional pets to find clues about her father''s whereabouts.' FROM games WHERE igdb_id = 258866 ON CONFLICT (game_id, language_code) DO NOTHING;
