INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Waluigi''s Foot Fault', 'Waluigi''s Foot Fault was a Flash game developed by Nintendo in 2000. The game was made to promote Mario Tennis for the Nintendo 64 and was discovered in a Nintendo Power magazine article. In this game, the player is tasked with clipping Waluigi''s toenails and catching them with a jar in which points are earned.' FROM games WHERE igdb_id = 231705 ON CONFLICT (game_id, language_code) DO NOTHING;
