INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gekitotsu-toma-larc-tomarunner-vs-larc-en-ciel', 44761, '2000-08-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co706r.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sco7af.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gekitotsu Toma L''Arc: Tomarunner Vs L''Arc En Ciel', 'Gekitotsu Toma L''Arc: TomaRunner vs L''Arc-en-Ciel is a Japan-exclusive racing game for the PlayStation. It is the sequel to TomaRunner and includes members of the Japanese band L''Arc-en-Ciel as playable characters. Each member of the band voices the in-game characters themselves. The L''Arc-en-Ciel songs that play within the game are "Driver''s High", "Stay Away", "Route 666", "Trick", and "Niji". The game was popular enough to receive a PS one Books re-release on December 21, 2001. The dream has finally become reality with the help of L''Arc en Ciel! Every fan must have this! And of course, there is fun to be had with this game. This summer, why don''t you try the Tomarunner experience for yourself?' FROM games WHERE igdb_id = 44761 ON CONFLICT (game_id, language_code) DO NOTHING;
