INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('densha-de-go-nagoya-tetsudou-hen', 72000, '2000-01-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob3d1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar8gb.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Densha de Go! Nagoya Tetsudou-hen', 'A release not seen in arcades, this Densha de Go! entry focuses on Meitetsu''s railroad lines in Nagoya, including the series'' only monorail. You play as a train engineer which serve the Meitetsu Nagoya line in Japan. There are many kinds of trains that you can drive, from express trains to monorails. Some trains are locked until you finish a mission, for example you can only drive monorails until you''ve finished the commuter and express train missions. All of the game parts, except the menu and station names, are in Japanese. In addition or the Meitetsu Nagoya Line, coverage includes Meitetsu Inuyama Line, Meitetsu Minomachi Line and Meitetsu Monkey Park Monorail Line. This was the first version to feature a monorail, and also featured a Meitetsu hybrid light rail route which ran both on regular train lines and as a sort of urban tram on special lanes in city streets. Part of the gameplay of this required the user to stop for regular traffic signals and avoid car traffic. This was the Densha de Go player''s first opportunity to drive a vehicle much lighter (and thus shorter stopping distance) than standard trains. In this version, the driver must sound the horn before beginning to accelerate out of a station. This is unique to this title. The gameplay, physics, and strictness of this version were all somewhat relaxed compared to previous versions. The game was published by Taito for the Sony PlayStation in Japan on January 27, 2000. It was later ported to the PC by Unbalance on December 1, 2000. The PS1 version later received a re-release as part of D3Publisher''s Simple 1500 series of budget games, as Simple 1500 Series Vol. 102: The Densha Untenshi - Densha de Go! Nagoya Tetsudou-hen, on August 29, 2002.' FROM games WHERE igdb_id = 72000 ON CONFLICT (game_id, language_code) DO NOTHING;
