INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('beatmania-core-remix', 97183, '2000-11-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ccm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8e9i.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beatmania Core Remix', 'Beatmania Core Remix is a rhythm game developed by Konami. It is the ninth game in the beatmania series and is part of the BEMANI franchise. The game is played with a controller with one turn table and 5 keys, three white and two black. On the screen you will see bars moving from the top to bottom in columns representing each of the keys and the turntable. When the bars reach the judgement line it is time to scratch. The game focuses on remixing the songs from the first two game, where every song features a normal and remixed version. it is the first game that lets you change the modifiers from the music select screen, which becomes standard later in the series, but only only when the game is in event mode. Since the game focuses on remixes no songs from clubMIX was brought over. Instead 17 songs from beatmania and beatmania 2ndMIX was included and remixed. An additional 7 brand new songs was also included for a total of 41 songs.' FROM games WHERE igdb_id = 97183 ON CONFLICT (game_id, language_code) DO NOTHING;
