INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Visual Pinball', 'Visual Pinball is a freeware and source available video game engine for pinball tables and similar games such as pachinko machines. It includes a table editor as well as the simulator itself, and runs on Microsoft Windows. It can be used with Visual PinMAME, an emulator for ROM images from real pinball machines.' FROM games WHERE igdb_id = 99113 ON CONFLICT (game_id, language_code) DO NOTHING;
