INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Buzz Lightyear of Star Command', 'Buzz Lightyear of Star Command is a Windows PC game created by Traveller''s Tales with Disney Interactive and PIXAR in 2000. The game consists of multiple planets, each with a villain on it. In each level, the players race the villain to their getaway destination. Then, they engage in a one-on-one battle with the villain, which usually requires destroying an energy shield surrounding the villain.' FROM games WHERE igdb_id = 19675 ON CONFLICT (game_id, language_code) DO NOTHING;
