INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Power Rangers: Lightspeed Rescue', 'The Nintendo 64 version features 3D action-based gameplay involving the Rangers, their vehicles, and Megazords. It supports 1 or 2 players simultaneously. Villains from the show, such as Diabolico, serve as antagonists; and the game features voice clips from the actual Power Rangers Lightspeed Rescue cast. The game is also compatible with the Nintendo Controller Pak for saving progress.' FROM games WHERE igdb_id = 3290 ON CONFLICT (game_id, language_code) DO NOTHING;
