INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Digimon: Quest to Save the Net', 'Quest to Save the Net was a Digimon Flash game created to promote Digimon: The Movie on the now defunct Fox Kids official website. At one point, the site allowed the player to upload their high scores. The game was also included in a CD-ROM extra disk which came packaged with VHS and DVDs of Digimon: The Movie.' FROM games WHERE igdb_id = 338409 ON CONFLICT (game_id, language_code) DO NOTHING;
