INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hunter X Hunter: Maboroshi no Greed Island', 'Hunter X Hunter: Maboroshi no Greed Island is a PlayStation Role-Playing entry in the Hunter X Hunter series. It''s an RPG with randomly generated dungeons. As a novice hunter, explore the mysterious Greed Island along various other characters from the anime. The island''s towns and cities have dungeons that seem to change when you go in them.' FROM games WHERE igdb_id = 60607 ON CONFLICT (game_id, language_code) DO NOTHING;
