INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('disneys-the-little-mermaid-ii', 45043, '2000-09-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7x2e.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7hsc.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s The Little Mermaid II', 'Fourteen years have passed since Ariel first defeated Ursula, married Prince Eric, and got herself a pair of legs. Now her daughter, Melody, has decided to go against her mother''s wishes to search the ocean for the city of Atlantis. Children begin the adventure as Ariel, reliving the events of the first movie. Once they defeat Ursula, kids change over to Melody and start their search for Atlantis. Disney did an excellent job making the controls simple enough for even young children to use. The goals and obstacles are also fairly simple- collect coins and pearls, for example. Even more impressive are the spoken instructions that accompany the on-screen text.' FROM games WHERE igdb_id = 45043 ON CONFLICT (game_id, language_code) DO NOTHING;
