INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Animorphs: Shattered Reality', 'The Animorphs are Jake, Rachel, Marco and Cassie, a group of children with the power to morph into animals as they battle the evil Yeerks and keep the world safe, while also dealing with the trials and tribulations involved with school, friends and parents. The book series by author K.A. Applegate has more than 32 million copies in print and there is a popular TV show airing on Nickelodeon. In the PlayStation game Animorphs - Shattered Reality, the characters find themselves in a time warp. You must help them gather the shards of the Time Matrix Crystal and restore the timeline back to normal. You can play as any of the Animorphs as you battle The Yeerks and Visser 3.' FROM games WHERE igdb_id = 43927 ON CONFLICT (game_id, language_code) DO NOTHING;
