INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('power-spike-pro-beach-volleyball', 44888, '2000-12-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2nrz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scmjsw.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Power Spike: Pro Beach Volleyball', 'Put away that suntan lotion, because you''re not going to need it for this beach volleyball game. That''s not to say the action isn''t hot, as you form a two-person team and battle the superstars of volleyball. Licensed by the FIVB, POWER SPIKE PRO BEACH VOLLEYABALL features over 40 real heroes of the pro circuit, such as Gabrielle Reece and Sinjin Smith. You''ll play in real-life environments set in 14 different locations spanning the globe. Travel to Sydney, Osaka, Los Angeles, and lots of other great cities as you spike and dig your way to hard-fought victory. If you''d like to see how your own creations fare against the world''s best, create your own player based on a list of physical traits and abilities, then pick a partner and serve it up. Real volleyball physics are in place, making every bump and spike look and feel like the real thing. The graphics and animations will rock your world as you play in several competitive modes. If you have a Multi-tap and four controllers, you can even play a four-player extravaganza, each player taking on a different star or created athlete in a two-on-two match-up.' FROM games WHERE igdb_id = 44888 ON CONFLICT (game_id, language_code) DO NOTHING;
