INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'realMyst', 'realMyst is a 3D remake of the 1993 adventure game Myst, developed by Cyan and released in 2000. It replaces the original’s static, pre-rendered images with fully explorable real-time 3D environments. The game retains the same story and puzzles while adding free movement and dynamic weather effects. Players explore the island and connected Ages to uncover the mystery behind its inhabitants.' FROM games WHERE igdb_id = 16198 ON CONFLICT (game_id, language_code) DO NOTHING;
