INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blues Brothers 2000', 'Start out as Elwood in prison and get the band together for the battle of the bands, which is in less than two days. After saving the guitarist, Cab and defeating the warden, Mac and Buster are waiting to be found in Chicago to complete and reunite your crew!' FROM games WHERE igdb_id = 3425 ON CONFLICT (game_id, language_code) DO NOTHING;
