INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kaseki no Uta', 'Kaseki no Uta is an adult romance adventure game released by âge on January 28, 2000. God created man. And man created "dolls". But what is the difference between these "dolls" and us humans? This is a rare and monstrous work that mixes several motifs often used as popular elements in recent years, and then weaves them into a science fiction story! However, what is this inexpressible sadness that lingers deeply in the heart at the end...' FROM games WHERE igdb_id = 334235 ON CONFLICT (game_id, language_code) DO NOTHING;
