INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'X-Men: Mutant Wars', 'Released in 2000 for the Game Boy Color, X-Men: Mutant Wars is a side-scrolling beat ''em-up game and the second X-Men title for the system. Its launch was synchronized with the release of the X-Men film on DVD. The game''s narrative revolves around a menace posed by cyborgs terrorising the planet. Convinced that Magneto is behind the cyborgs'' actions, the X-Men are tasked with defeating him. Players can control characters like Wolverine, Storm, Cyclops, Iceman, and Gambit as they gear up for the impending battle to save the planet.' FROM games WHERE igdb_id = 49887 ON CONFLICT (game_id, language_code) DO NOTHING;
