INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dance-dance-revolution-3rdmix-ver-dot-korea2', 135387, '2000-05-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5u7v.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8cy2.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dance Dance Revolution 3rdMix Ver.Korea2', 'Two versions of Dance Dance Revolution 3rdMix were released in South Korea in March 2000. It is exactly like the original version of 3rd Mix, except that it fixes the Shuffle bug and adds seven Korean pop songs and one from the original to 3rdMix and SSR modes. An update to this version, Dance Dance Revolution 3rdMix verKorea2 was also released in South Korea in March 2000, adding 9 more K-Pop songs. The songs missing in the Asian version is still absent in this game, however. The exclusive songs from the first Korean version would be added to the Japanese version with the 3rdMix Plus update. However, due to censorship, Charmy now wears stockings. And OH NICK PLEASE NOT SO QUICK''s graphics were also censored.' FROM games WHERE igdb_id = 135387 ON CONFLICT (game_id, language_code) DO NOTHING;
