INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Mickey Mouse Toddler', 'In this collection of preschool activities, the player joins some well-known Disney cartoon characters to explore numbers, letters, and creativity. A different character introduces each activity (except for Pluto, who doesn''t speak) and briefly hints at what to do - the player interacts with most activities simply by moving the mouse over the screen to uncover hidden items, listen to sounds, explore color, etc. The graphics are pure Disney cartoon and quiet music plays in the background throughout the game.' FROM games WHERE igdb_id = 71630 ON CONFLICT (game_id, language_code) DO NOTHING;
