INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Colin McRae Rally 2.0', 'Colin McRae Rally 2.0 is a rally racing game that features the 1999-spec Ford Focus WRC, the 2000-spec Ford Focus RS WRC, Mitsubishi Lancer EVO VI Gr.A, Subaru Impreza WRC2000, Peugeot 206 WRC, Toyota Corolla WRC and SEAT Córdoba WRC, among other cars. The countries included are Kenya (gravel and tarmac), Finland (gravel and mud), United Kingdom (tarmac, mud and gravel), Sweden (snow and ice), Australia (loose pea gravel), Japan (1 stage in challenge mode, Tarmac and Mud), France (Corsica) (tarmac), Greece (rough gravel), and Italy (tarmac). The car featured on the front cover of the game was McRae''s Ford Focus WRC 2000 (V3 FMC).' FROM games WHERE igdb_id = 642 ON CONFLICT (game_id, language_code) DO NOTHING;
