INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Police 911 2', 'The second arcade light gun shooter with a camera that detects the player''s movements. Players can use body movements to hide behind objects and dodge (slow-moving) bullets. It was a video game with fairly accurate full-body motion detection, a very rare system in its time.' FROM games WHERE igdb_id = 97483 ON CONFLICT (game_id, language_code) DO NOTHING;
