INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Big Mountain 2000', 'Big Mountain 2000 is a wintersports game where you can choose to race downhill with either a snowboard or skis. There are various characters to choose from, each of them with different skills. Three game modes are available in total, in which free ride, slalom and giant slalom can be chosen as track styles; game modes include championship, time attack and also a battle mode for multiplayer challenges.' FROM games WHERE igdb_id = 3367 ON CONFLICT (game_id, language_code) DO NOTHING;
