INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Backyard Soccer: MLS Edition', 'Backyard Soccer MLS Edition gives you the chance to kick the ball around with America''s professional soccer stars from the MLS and star women players from the US Olympic team. Player''s create a junior avatar of themselves and draft a team from other backyard kids and kid versions of 15 famous American soccer players then deck themselves out in their favorite uniforms and hit the field. Standard sports simulation game types are available including exhibition games and season play but the emphasis is on fun and accessibility for all ages.' FROM games WHERE igdb_id = 69634 ON CONFLICT (game_id, language_code) DO NOTHING;
