INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kids Station: Asobou! Hanasou! Guru-guru Town Hanamaru-kun', 'Kids Station: Asobou! Hanasou! Guru-guru Town Hanamaru-kun is based on the anime and features a big collection of different kind of mini-games in which the young players can learn about maths, animals, shapes, etc. There are also some mini-games about coordination, timing character movement etc.' FROM games WHERE igdb_id = 148374 ON CONFLICT (game_id, language_code) DO NOTHING;
