INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cyber Troopers Virtual-On: Oratorio Tangram - M.S.B.S. Ver. 5.66', 'Cyber Troopers Virtual-On: Oratorio Tangram - M.S.B.S. Ver. 5.66 is the last of three major revisions to Cyber Troopers Virtual-On: Oratorio Tangram, a sequel to Cyber Troopers Virtual-On. Ver. 5.66 makes significant changes to Oratorio Tangram, upgrading the aesthetics to suit the improved NAOMI hardware, introducing three new Virtuaroids, and including VMU support, allowing the game to interact with the Sega Dreamcast version of Ver. 5.4(5).' FROM games WHERE igdb_id = 172535 ON CONFLICT (game_id, language_code) DO NOTHING;
