INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arle no Bouken: Mahou no Jewel', 'Arle no Bouken: Mahou no Jewel is a role playing game developed and published by Compile for the Game Boy Color; it was released on March 31, 2000. The game revolves around the collection of cards, each of which contains a monster. Madou Monogatari/Puyo Puyo protagonist Arle Nadja and her usual foes, such as Skeleton T and Schezo Wegey, use these monsters to assist them in battle.' FROM games WHERE igdb_id = 50020 ON CONFLICT (game_id, language_code) DO NOTHING;
