INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('happyland-adventures', 50094, '2000-05-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1vqz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7hdt.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Happyland Adventures', 'HappyLand Adventures is a platforming game with puzzle elements. In HappyLand Adventures you play as a rabbit running around saving small animal like creatures called happylanders. When you touch them, they start following you around. These creatures are often hidden on the map, and it requires you to explore each map to find them all. Once you have one (or more) you can drop them off at specialized safe zones. If you die, any happylanders following you will be returned to their original location. In order to finish a level you must drop off a certain amount of happylanders. When you have done so a message will tell you that the level exit is open Along the way you meet people that you can talk to in order to get hints as to where to go next in order to proceed through the level. You can also pick up fruits that you find to gain more points, and hearts that function as a health bar. Each enemy you hit will take one heart away, if you hit an enemy when you have no hearts left you will die. You are out to rescue the happylanders, small animal like creatures. Rescuing these will rid the world of evilness. As a nice bonus, the download includes a level editor you can use to create your own levels, and you can download extra ones from the game''s website. Thumbs up for this charming freeware underdog.' FROM games WHERE igdb_id = 50094 ON CONFLICT (game_id, language_code) DO NOTHING;
