INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 1500 Series Vol. 36: The Renai Simulation - Natsu-iro Celebration', 'The Renai Simulation: Natsu-iro Celebration is a classic adventure dating simulation game. The game begins at the beginning of august when Kimi is a young student receive a call from her father telling her to return to home in 21 days. So she decided to enjoy those days having fun with her classmate friend. They will go around the town and meet different people. Everytime that the game is played the personality of the people changed making each time a different experience for the player. The game features 11 different main characters to interact.' FROM games WHERE igdb_id = 203021 ON CONFLICT (game_id, language_code) DO NOTHING;
