INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Riding Champion: Legacy of Rosemond Hill', 'You play as Annie, who has inherited a horse that is stabled at Rosemond Hill, and your goal is to win the prestigious Kingswood Championship. To achieve that goal you have to care for your horse, like feeding and cleaning it, and train it in show jumping, endurance riding and cross country riding, to get in top shape for several championships along the way. Explore the horse farm to engage with Annie’s friends and discover the secrets of Rosemond Hill.' FROM games WHERE igdb_id = 64116 ON CONFLICT (game_id, language_code) DO NOTHING;
