INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('truck-kyousoukyoku-ai-to-kanashimi-no-rodeo', 327364, '2000-12-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co98nc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar392i.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Truck Kyousoukyoku: Ai to Kanashimi no Rodeo', 'The PS2 port of this game betters the original with new tracks and additional graphical details. As the truck maneuvering maniac, your goal is to race against competing truckers any which way but loose. Drive on sidewalks, search for shortcuts, discover secret roads and plunge headlong into traffic with no reservation. You are, after all, a maniac. Upon winning races, the player gets a can of aerosol to paint designs and emblems on the body of the truck. The sides, top, back, and head of the vehicle are open canvases for you to drop paint and swirl a menacing symbol or a nature panorama. Preset designs may be chosen or you can create your own doodles which help you help your truck emote. The action is hot and the paint jobs add to the ambience.' FROM games WHERE igdb_id = 327364 ON CONFLICT (game_id, language_code) DO NOTHING;
