INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pocket Digimon World', 'Original version of Pocket Digimon World using the PocketStation, a PlayStation accessory device. The exclusive digimon of this version are Agumon, Biyomon and Veemon. The actual main game primarily happens in the PocketStation. In the PocketStation, you can raise your Digimon and battle it either with in-game Digimon or a friend''s PocketStation wirelessly over IR connection. You can also connect it to other Bandai Digimon games and products.' FROM games WHERE igdb_id = 58948 ON CONFLICT (game_id, language_code) DO NOTHING;
