INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('asterix-search-for-dogmatix', 50019, '2000-07-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9q8r.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Astérix: Search for Dogmatix', 'If you have trouble choosing between an adventure game with a suspenseful, in-depth investigation and a game of skill made for joystick fanatics, "Asterix: search for Dogmatix" is just for you! If you play in "adventure" mode, you set out to search for Dogmatix in six worlds and 30 levels (taking you on journeys throughout Gaul, Egypt, Rome, etc.). And the dozen or so mini-games in "instant fun" mode are sure to keep your fingers busy between two stations on the underground. There''s a catch, though: to access the whole set of mini-games, you have to win Bonus Tokens by playing in "adventure" mode. By Belenos, this is a game for the truly indomitable!' FROM games WHERE igdb_id = 50019 ON CONFLICT (game_id, language_code) DO NOTHING;
