INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Looney Tunes Racing', 'Rev your engines - It''s time to burn some Looney Tunes rubber! ACME Corporation, the corporate juggernaut behind such successful products as the Acme Disintegrator Gun and the Acme Portable Hole, is sponsoring a number of racing contests all over the universe for the Looney Tunes characters to compete for the looniest racing champion title.' FROM games WHERE igdb_id = 8135 ON CONFLICT (game_id, language_code) DO NOTHING;
