INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Artist: Communication Kit', 'Mario Artist: Communication Kit serves as an add-on and accessory to the other Mario Artist games. It allowed players to connect to the Internet via RandNetDD and show off their creations to other players. While connected, players can use their characters to explore a virtual 3D community. There is also exclusive content on the disk that can be imported to the other Mario Artist titles.' FROM games WHERE igdb_id = 79479 ON CONFLICT (game_id, language_code) DO NOTHING;
