INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Trek: Voyager - Elite Force', 'This first person shooter set in the Star Trek universe lets you take control of a member of the Starship Voyager crew as you combat the Borg and other enemies. The game utilizes the Quake 3 engine for incredible graphics as you travel through many familiar locations --Voyager, a Borg cube, a Klingon Bird of Prey, and more. The game also requires you to solve missions with the help of intelligent computer controlled teammates and allies.' FROM games WHERE igdb_id = 877 ON CONFLICT (game_id, language_code) DO NOTHING;
