INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bass-landing', 43922, '2000-10-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/ilhrolte4trkjsjxdv8m.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bass Landing', 'Designed for the armchair angler in mind, Bass Landing captures the essence of being on an actual lake and boat without the hassle of reaching into your tackle box and pulling back a handful of slime! There are five different lakes in all, ranging from the murky Lunker Lake to the mountainous clarity of Crystal Lake. Each contains natural and manmade hazards (branches, poles, rocks) and different kind of fish--depending on the kind of fish you want, choose your lake accordingly.  For instance, the Silver Carp can only be found in dark, murky lakes or swamps and the Spotted Bass resides in the chilly, colder water areas. While the name of the game is bass, there are 14 different types of fish including the small but feisty Blue Gill, massively dynamic Carp, and the multiplying Rainbow Trout.  In addition to his or her game, the armchair fisherman will need to know how his fishing rod works and what lures to use on the various fish. There are fifty different tools in all ranging from Spinner Bait to the MHB-665 Bait Rod--one will want to know the functions of each lure and rig and choose an appropriate rod for the type of fish being hunted.' FROM games WHERE igdb_id = 43922 ON CONFLICT (game_id, language_code) DO NOTHING;
