INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('empire-of-the-ants', 47102, '2000-04-20', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co22up.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar35qp.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Empire of the Ants', 'Empire of the Ants takes you into the undergrowth of the frantic world of colonization and dominance within the insect kingdom. Build up huge colonies, lead your armies into battle for supremacy, hunt down food, and breed to improve your numbers. Featuring 11 missions, 13 different breeds of ant to control, and numerous units such as exploding soldier ants, queen''s gunners, and doorkeepers. Real-time effects include winter and summer seasons, rain, wind, and night/day. Beautifully rendered 3-D graphics depict a lavish insect kingdom. Play alone or in multiplayer mode over a network. Innovative AI reproduces the instinctual behaviors of every insect.' FROM games WHERE igdb_id = 47102 ON CONFLICT (game_id, language_code) DO NOTHING;
