INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('never7-the-end-of-infinity', 18018, '2000-12-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2271.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3a10.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Never7: The End of Infinity', 'Never7: The End of Infinity is the first title in the Infinity series, and is followed by Ever17: The Out of Infinity, Remembe 11: The Age of Infinity, 12Riven: The Psi-Climinal of Integral, and Code_18. In the game, the player takes the role of Makoto Ishihara, a college student who attends a seminar camp on an island together with three other students; he also befriends three other people who he meets on the island. The game takes place over the course of a week, and consists of the player reading the story, occasionally making choices that affect the direction of the plot; on the sixth day, one of the female characters dies, and the game moves back in time to the beginning, letting the player use knowledge from the first set of six days to make new choices, to try to prevent the character''s death.' FROM games WHERE igdb_id = 18018 ON CONFLICT (game_id, language_code) DO NOTHING;
