INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('alizarin-tetris', 93028, '2000-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9dor.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scvavy.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alizarin Tetris', 'Alizarin Tetris is a freeware Tetris variant with several game modes and other features. The game area is 10 x 20 tiles in size and as standard every piece that drops down can consist of up to four smaller pieces which are affected by gravity. If you place two pieces of the same color together they will mend together into one piece. There are six game modes: Solo Normal Game, Solo Scoring Marathon, Solo vs. Computer, 2 Players @ 1 Keyboard, 2 Players. Use Network, Computer vs. Computer. If the standard tetris pieces feels too uninteresting to play with you can select to play with two other sets of pieces: "Planar Pantominoes" and "One-To-Five-Ominoes". To make the game even more interesting you can activate the "Power Pieces"-option. A Power Piece can be one of four different kinds: The bomb (destroys all adjacent tiles), The Down (pushes each tile directly beneath it down as far as it can go), The Drip (all non-garbage tiles adjacent to it change to be the color most commonly occurring on the board) and The Skull (destroys all non-garbage tiles adjacent to it). As standard there is no sound in the game but the user can add his/her own sound. The graphic style of the game can also be changed. There are 12 built in styles and additional styles can be created by the user.' FROM games WHERE igdb_id = 93028 ON CONFLICT (game_id, language_code) DO NOTHING;
