INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'El Tesoro de Isla Alcachofa', 'Our name is Jim, a young man who wants to open a future in the world of pirates and has done many different jobs and of all kinds. This time we are going to look for Captain Flint''s treasure and start the game remembering how everything happened and how we arrived at Alcachofa Island where he was buried.' FROM games WHERE igdb_id = 94443 ON CONFLICT (game_id, language_code) DO NOTHING;
