INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Blaze', 'Dragon Blaze is a vertical scrolling shoot ''em up arcade game released in 2000 by Psikyo. It was ported in 2004 to the PlayStation 2 as part of the Psikyo Shooting Collection Vol. 3:Sol Divide & Dragon Blaze compilation. The game was later also released on its own for the PS2 in Europe by 505 Games.' FROM games WHERE igdb_id = 39659 ON CONFLICT (game_id, language_code) DO NOTHING;
