INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('superbike-2001', 887, '2000-10-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/gsss1c7joz1qg25udpli.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Superbike 2001', 'Superbike 2001 showcases perfect reproductions of all 13 tracks of the Superbike World Championship and all the bikes found in races: Ducati, Aprilia, Honda, Suzuki, Kawasaki, Yamaha, e Bimota.  The only official simulation of the Superbike Championship will let you race against the best riders taking part in this competition: teams and tracks (including Oschersleben, Imola and Valencia) are completely updated in order to include all the new elements of the championship that just ended.  Available Game modes are: Quick Start, to take part to a race without preliminary stages; Quick Race, to practice, qualify and finally race; and Championship, where you can take part in all the Superbike season on all thirteen tracks.' FROM games WHERE igdb_id = 887 ON CONFLICT (game_id, language_code) DO NOTHING;
