INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('skyfighters-1945', 339151, '2000-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9n4t.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scw6lq.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SkyFighters 1945', 'SkyFighters 1945 puts you in the cockpit of a World War II-era fighter plane and sends you off to do battle in the skies over Europe or the South Pacific. You can embark on any of 30 missions, each with unique objectives, diverse topographies, and distinct enemy planes. The game supports network play by as many as eight players on a LAN or the Internet. You can also compete head-to-head in a dogfight against a computer-controlled aircraft. SkyFighters lacks the intricate flight-control systems that high-end flight simulators offer, and its garish graphics sometimes give the game a cartoonish feel. But the mechanics of flying aren’t difficult to master, and the animation is fast and fluid, even on low-end systems.' FROM games WHERE igdb_id = 339151 ON CONFLICT (game_id, language_code) DO NOTHING;
