INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PokéROM: Psyduck', 'This PokéROM is part of a set of educational games featuring creatures from the Pokémon universe. The game contains mathematical challenges for children up to a fifth grade level; upon completion, the player will be awarded with pictures of Psyduck. A competitive trivia mode supports up to four players in a race to the finish line. Players take turns to answer questions pertaining to such subjects as geography, grammar, and Pokémon knowledge, with correct answers moving the player closer to the goal.' FROM games WHERE igdb_id = 218524 ON CONFLICT (game_id, language_code) DO NOTHING;
