INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Baroque Syndrome', 'The game is played as an interactive novel, with 2D still pictures of settings and characters being the main graphic elements, and all actions being described via scrolling texts. At several intervals you will have to make a choice that branches the plot in different directions, but that''s all the interaction you get to make.' FROM games WHERE igdb_id = 73872 ON CONFLICT (game_id, language_code) DO NOTHING;
