INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heroes Chronicles: The World Tree', 'The World Tree is the fifth part of Heroes Chronicles, following Clash of the Dragons and preceding The Fiery Moon.  As a Barbarian, Tarnum defends the World Tree in northeastern Antagarich from evil Barbarians and Necromancers led by the demigod Vorr. This was available as a free download for those who purchased two Heroes Chronicles games.' FROM games WHERE igdb_id = 13363 ON CONFLICT (game_id, language_code) DO NOTHING;
