INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 1500 Series Vol. 49: The Casino', 'Simple 1500 Series vol. 49: The Casino is a gambling game with some adventure elements, the game has a story mode in which the player is a man that arrives at a town and when he is in the airport he lost all his money but finds a coin of 50 and he decide to play in the casino to earn enough money to leave town. In the Casino he can play gambling games like Roulette, Card Slot, Card games, Horse racing bet, Tetris, etc' FROM games WHERE igdb_id = 203033 ON CONFLICT (game_id, language_code) DO NOTHING;
