INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kirby-tilt-n-tumble', 3729, '2000-08-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1wbo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3nre.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kirby Tilt ''n'' Tumble', 'Peacefully sleeping in his Dream Land, Kirby drifts lazily amongst the beauty of the sky. A beauty that King Dedede cannot abide with. Jealous of the sky''s wondrous splendor, King Dedede has acquired a tool that will let him steal the night''s stars, plunging the world into eternal drab daylight. When Kirby awoke, he found that it was still daytime. And evermore, it would be daytime, unless Kirby made the journey to find King Dedede and recover the stars to restore the night''s sky. So begins the latest Kirby adventure, another action adventure with the morphing marshmallow in a starnge fantasy world. However, the one thing separating this latest adventure is the control scheme. Here, you don''t control Kirby directly. Instead, you guide Kirby by tipping your system to roll the little round pink puff through a series of mazes. If you get in a jam you can make Kirby jump by a controller press, and Kirby can still acquire weapons from other enemies, but the real skill is using the tilting to your advantage.' FROM games WHERE igdb_id = 3729 ON CONFLICT (game_id, language_code) DO NOTHING;
