INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mortal Kombat: Special Forces', 'Take on the role of Mortal Kombat character Jax, as you descend into the realm of Mortal Kombat in search of arch- villain, Kano. As you make your way through the game, you will delve deeper into one of the most interesting and enigmatic stories in the Mortal Kombat universe. Battle your way through complex 3D levels. Destroy your enemies using never-before-seen special moves and combos, all leading to an unforeseen climactic ending.' FROM games WHERE igdb_id = 1623 ON CONFLICT (game_id, language_code) DO NOTHING;
