INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arthur Yahtzee: The Curse of Hell''s Cheesecake', 'In this comedic espionage game, you play as Agent Arthur Yahtzee of the Special Secret Service. Your mission is to stop the most evil and sadistic human in the multiverse, Doctor Diablo, from ever using Hell’s Cheesecake to return to his home dimension.' FROM games WHERE igdb_id = 217857 ON CONFLICT (game_id, language_code) DO NOTHING;
