INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('densha-de-go-3-tsuukinhen', 63706, '2000-03-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2yz8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc9evc.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Densha de GO! 3 Tsuukinhen', 'Densha de Go! 3 Tsuukin-hen (loosely translated to "Go by Train! 3 Commuting Edition", also known as "Let''s Go by Train! 3") is an electric train driving simulation game developed and released by Taito for arcades in Japan on March 2000. The sequel to the 1998 game Densha de Go! 2 Kousoku-hen, Densha de Go! 3 uses updated arcade hardware for improved 3D graphics (such as a higher-resolution user interface and improved models for both the trains and environment) while revamping the scoring calculation, adding online leaderboards, adding multiple time-of-day options (including morning, noon, evening, and night), and including two additional game modes ("Family Mode" for beginner players and "Tetsujin Mode" for advanced players). It features a new set of real-life train routes, including the Sasaguri Line, the Kagoshima Main Line, the San''yō Main Line, the San''in Main Line, the Chūō Main Line, and the Chūō-Sōbu Line. The game later received an update on October 2000, known as Densha de Go! 3 Tsuukin-hen: Daiya-kaisei (loosely translated to "Go by Train! 3 Commuting Edition: Diagram Revision"). This version updates some minor things, including the timetable and scoring calculation. It is the last arcade entry in the series in 14 years, prior to Densha de Go!! The original version was later ported to the PlayStation 2 on March 15, 2001, while the Daiya-kaisei version was later ported to the PC by Unbalance. The PS2 version also included a demo of Densha de Go! Shinkansen on a bonus disc, and later received a re-release (sans demo) as part of D3Publisher''s Simple 2000 series of budget games, as Simple 2000 Series Vol. 22: The Tsuukin Densha Utenshi - Densha de Go! 3 Tsuukin-hen, on March 27, 2003.' FROM games WHERE igdb_id = 63706 ON CONFLICT (game_id, language_code) DO NOTHING;
