INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('densha-de-go-ryojou-hen', 79442, '2000-10-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2yzw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar8gg.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Densha de GO! Ryojou-hen', 'Taito''s 13th entry in its train simulation series, this one focused on electric trams and light rails. Ganbare Unten-shi!! (loosely translated to "Good Luck, Driver!!") is an electric train driving simulation game developed and released by Taito for arcades in Japan on October 2000. A spin-off of the Densha de Go! series (and using the same engine as Densha de Go! 3 Tsuukin-hen), Ganbare Unten-shi!! focuses on light rail transit with two routes: the Enoshima Electric Railway and the Iyo Railway. While much of the game is the same as the main series, it modifies the braking and throttling controls for added precision and adds controls for operating the vehicle''s doors. Due to street traffic, maintaining a timetable is not as strict as previous entries and the time-based penalty system is replaced with a "lives"-based one. The game was later ported to both the PlayStation 2 (on July 25, 2002) and PC (by Unbalance on June 5, 2003) as Densha de Go! Ryojou-hen (loosely translated to "Go by Train! Emotional Travel Edition"). This version features features an updated graphics engine (based on Densha de Go! Shinkansen) and adds four additional routes: two from the Keifuku Electric Railroad and two from the Hakodate Transportation Bureau.' FROM games WHERE igdb_id = 79442 ON CONFLICT (game_id, language_code) DO NOTHING;
