INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metal Fatigue', 'Lead one of the three warring factions to victory as one of three brothers; Jonus, Stefan or Diego. Only one faction will stand above the rest in the end; Mil-Agro, Rimtech or Neuropa. The Hedoth technology will decide the course of the war, in particular the end.' FROM games WHERE igdb_id = 24128 ON CONFLICT (game_id, language_code) DO NOTHING;
