INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Genesys', 'Educational historical FMV puzzle game. Follow the evolution of human civilization and technology from prehistory to modern times and solve puzzles tied to what you''ve learned to progress. Educational video game, The player is guided by Jeanne Moreau through Claude Richardet''s game. The game allows the player to discover the key stages of the evolution of various human societies around the world.' FROM games WHERE igdb_id = 83196 ON CONFLICT (game_id, language_code) DO NOTHING;
