INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('schiffbruch', 76251, '2000-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/jp7xcrruptoqxtumrgpk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/orbxkiqthchoiw5o1sdp.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Schiffbruch', 'Schiffbruch ("Shipwreck") is a freeware survival game where the player controls a desperate castaway trying to subsist on the resources of a small equatorial island after his ship sunk near the coast. The game renders the randomly-generated isle terrain and its features with tiny isometric graphics, with areas gradually becoming visible as the main character explores the surroundings. The large right side interface shows a small map of the revealed terrain at the top, a menu with action commands below it and several meters at the bottom for daylight time, water, food, and health.  The player has to guide the little man around the land, and give him orders to search around for food, useful materials and other essentials. Unlucky but resourceful, he can assemble tools, build tents, set SOS signs and do other work, foraging nearby bushes for food and drinking water from winding streams. When evening starts, he automatically collapses on the floor and goes to sleep, and the player must make sure he''s near his makeshift hut at night, otherwise the next day starts with a substantial health hit. His chances of being rescued are displayed as a percentage number below a lifesaver icon at the top. The game ends, of course, when the main character dies for some reason.' FROM games WHERE igdb_id = 76251 ON CONFLICT (game_id, language_code) DO NOTHING;
