INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Midnight Club: Street Racing', 'Midnight Club brings the action of high speed driving and adventure to the Game Boy Advance. The concept behind this game derives from the illegal races of real-world Midnight Clubs. The core gameplay consists of races of high-speed maneuvering through completely open city streets. Live life in the insane lane, escape the law and accumulate an arsenal of vehicles.' FROM games WHERE igdb_id = 6509 ON CONFLICT (game_id, language_code) DO NOTHING;
