INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metal Slug 2nd Mission', 'Metal Slug: 2nd Mission is an Action game, developed by Ukiyotei and published by SNK, which was released in Japan in 2000. Take control of the Metal Slug tank on the NGPC once again, this time to defeat the rebel strike force "Phantom." Travel through 38 stages in a non-linear battle path defeating enemy troops and rescuing hostages. Pilot the Metal Slug tank, Slug Flyer combat jet, and the Slug Sub submarine and fire the heavy machine gun, rocket launcher, and fire gun. Two unique playable characters, a list of rescued hostages, and a time attack mode add depth to this side-scroller.' FROM games WHERE igdb_id = 43984 ON CONFLICT (game_id, language_code) DO NOTHING;
