INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Screamer 4x4', 'Screamer 4x4 lets players loose on rough terrain in a range of modified off-road vehicles, ranging from the simple Land Rover to the massive RÁBA H18. Players compete in a series of time trial championships and trophies, earning new vehicles and upgrades as they go. There is a variety of play modes, including the option of a free drive (like Midtown Madness). Additionally, there is a range of multi-player games reminiscent of Carmageddon.' FROM games WHERE igdb_id = 7143 ON CONFLICT (game_id, language_code) DO NOTHING;
