INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mike-tyson-boxing', 23452, '2000-10-31', 33, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4o41.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5kmx.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mike Tyson Boxing', 'Mike Tyson Boxing is a 3D simulation based on one of the best-known fighters of the ''80s and ''90s. The game offers three main modes of play: "Vs." mode offers fast, arcade-style matches in which the loser walks and the winner stays on to meet the next challenger. "Showcase" mode allows up to eight players and eight CPU boxers to meet for rotating tournament action. In "World" mode, the player starts with a rookie fighter and guides his career fight after fight through the ranks of contenders until he finally faces the champ for the belt. Mike Tyson Boxing features over 90 different boxers and 16 world-class venues. Fighters can interact with the ring environment and blood, sweat, and bruises are graphically depicted on the characters. Scoring is based on the point system used in real boxing and a special score bar helps players keep track of how they are doing in the heat of battle.' FROM games WHERE igdb_id = 23452 ON CONFLICT (game_id, language_code) DO NOTHING;
