INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('towers-lord-baniffs-deceit', 49990, '2000-07-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4zcm.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Towers: Lord Baniff''s Deceit', 'As the war rages on between Airatose and Sagon, a band of adventurers departs to join the war. However, their ship is damaged in a storm, and they stop on an undiscovered island known as Lamini. Lord Banniff gives the adventurers shelter and materials to repair their ship. On the eve of their departure, the adventurers discover something sinister about Lord Banniff. You must take control of one of the adventurers, each with relative strengths and weaknesses, and try to escape from Lord Banniff''s castle. Explore 15 levels, battle hundreds of monsters, and find useful items and weapons. If exploring the castle by yourself becomes tedious, use a link cable and have a friend join the adventure. Try to escape from Lord Banniff in TOWERS: Lord Banniff''s Deceit' FROM games WHERE igdb_id = 49990 ON CONFLICT (game_id, language_code) DO NOTHING;
