INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('need-for-speed-porsche-unleashed', 94, '2000-03-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9bt7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/qcvf5ppqdwhulynvm5pt.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Need for Speed: Porsche Unleashed', 'You''ve pushed yourself to the edge - now drive over it! Need for Speed Porsche 2000 lets you experience the adrenaline rush of high-speed driving with 74 different Porsche models dating from 1948 to 2000. Roar down the roadways in classic models such as the 1948 356 No.1, or push the state-of-the-art 2000 996 Porsche Turbo to its absolute limit. The choice is yours. Grid-based tracks feature 20 open road segments, and with the capacity for 4 people to play, this game lets you take part in a thrills ''n'' spills journey through Porsche''s fast-paced 50-year history. Fasten your seat belt!' FROM games WHERE igdb_id = 94 ON CONFLICT (game_id, language_code) DO NOTHING;
