INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RC Revenge', 'Players take control of a range of remote controlled cars and boats in an action packed racing game for the Sony PlayStation. Based around an enchanting movie Theme world, players take their cars through a number of genre styled levels, including horror, sci-fi and cartoons. Multiplayer split screen racing available in all modes of the game and a unique track editor allows you to create your own tracks to save on memory card and challenge your friends.' FROM games WHERE igdb_id = 94303 ON CONFLICT (game_id, language_code) DO NOTHING;
