INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pro-pool', 49952, '2000-10-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2v9j.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6k68.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pro Pool', 'Exciting billiards action comes to the Game Boy Color with PRO POOL. Play a match against the computer or a friend, or play the Single-Player Speed Match and try to clear all of the balls off of the table as quickly as possible. In Hustle mode, you take the role of a pool hustler, traveling from bar to bar placing bets on games. Ultimately, you want to win enough money to buy your own bar. In all of these modes, six different games can be played: 8 Ball, 9 Ball, 6 Ball, 3 Ball, straight pool, and speed pool. And the competition will never get stale thanks to the 64 different computer opponents to play. Plus, an outstanding physics engine makes this the most realistic pool game available for the Game Boy Color. Try to become a great hustler with PRO POOL.' FROM games WHERE igdb_id = 49952 ON CONFLICT (game_id, language_code) DO NOTHING;
