INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sno-pokeler', 237532, '2000-04-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa7q7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3xui.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sno Pokeler', 'Sno Pokeler allows the player to accessorize his PocketStation (not included with the game) and create your own Pokeler with accompanying Playstation 1 software. The player can customize his Pocketstation with different themes, characters faces, tones, etc. The PocketStation is a peripheral by Sony Computer Entertainment for the PlayStation home video game console. Categorized by Sony as a miniature personal digital assistant, the device features a monochrome liquid crystal display (LCD), infrared communication capability, a real-time clock, built-in flash memory, and a sound capability. Connecting to a PlayStation through a memory card slot, the PocketStation also functions as a PlayStation memory card. It was released exclusively in Japan on January 23, 1999. Software for the PocketStation was typically distributed as extras for PlayStation games, included in the CD-ROM, enhancing the games with added features. Stand-alone software could also be downloaded through the PlayStation console. The software is then transferred to the PocketStation for use. A built-in infrared data interface allows direct transfer of data such as game saves between PocketStation units, as well as multiplayer gaming.' FROM games WHERE igdb_id = 237532 ON CONFLICT (game_id, language_code) DO NOTHING;
