INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('beatmania-complete-mix-2', 92674, '2000-01-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2cbv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8e7j.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'beatmania complete MIX 2', 'beatmania completeMIX 2 is a rhythm game developed by Konami. It is the seventh game in the beatmania series and is part of the BEMANI franchise. The game is played with a controller with one turn table and 5 keys, three white and two black. On the screen you will see bars moving from the top to bottom in columns representing each of the keys and the turntable. When the bars reach the judgement line it is time to scratch. Difficulty levels were rearranged on a scale from 1 to 9, which remains as the standard for the rest of the series. Many older songs have new ANOTHER difficulty charts, some have a rearranged charts for their ANOTHER charts, making use of the preexisting assets to make a new sounding song. The HARD version charts from 5thMIX became ANOTHER charts in this version. The modifier CENTER PLAY has been added, making it possible to use the 2 player keys and 1 player turntable, for scratching with the left hand. HI-SPEED has been expanded with 2x-4x selection. beatmania completeMIX 2 is a compilation mix containing most of the songs from beatmania 4thMIX and beatmania 5thMIX (45 songs). 12 songs were lifted over from beatmania - beatmania 3rdMIX and 23 new songs were introduced. The total song list is 80 songs.' FROM games WHERE igdb_id = 92674 ON CONFLICT (game_id, language_code) DO NOTHING;
