INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Destructo 2', 'Destructo 2 is a simple color-matching puzzle game similar to Mr. Driller, originally released as part of a budget series in Japan. The main objective is to guide a cartoon character moving through an ascending pile of multicolored tiles, pushing the available blocks to create clusters of the same color. Groups of four or more tiles of matching colors can be removed by punching one of the connected blocks, with the vacant space being occupied by the falling stacks on top. The descending tiles that end up rearranged in new color clusters are automatically eliminated and give combo points.' FROM games WHERE igdb_id = 203032 ON CONFLICT (game_id, language_code) DO NOTHING;
