INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Clone-A-Doodle-Doo', 'Clone-a Doodle Doo is a Dexter''s Laboratory flash game that was formerly available the Cartoon Network website. Players use Dexter’s “FenceBlaster” to corral cloned chickens into enclosures without zapping them.' FROM games WHERE igdb_id = 357350 ON CONFLICT (game_id, language_code) DO NOTHING;
