INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Air', 'Air is a Japanese visual novel developed by Key that follows the story of the life of Yukito Kunisaki, a traveling showman searching for the "girl in the sky". He arrives in a quiet, seaside town where he meets three girls, one of whom is the key to the end of his journey. The gameplay in Air follows a branching plot line that offers pre-determined scenarios with courses of interaction and focuses on the appeal of the three female main characters by the player character.' FROM games WHERE igdb_id = 270385 ON CONFLICT (game_id, language_code) DO NOTHING;
