INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('martial-masters', 39386, '2000-04-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9paq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/schm3e.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Martial Masters', 'At the end of the Qin''s Dynasty, the government weakened by corruption was attacked by foreign influences. The people were flung into misery and became quite unsatisfied with the situation. They did not believe in the government anymore and turned their faith back to religion. The White Lotus sect saw this as an opportunity and took over. They claimed to help the government to defeat foreigners and bring peace to the world. Their Ideology was quickly adopted. Everything related with the Western world was killed or destroyed. Anyone against this principal was considered an enemy and accused of being bound with the devil. Dragon of Martial Master and Master Huang of Po Chi Lam could not accept these outrageous actions so they band together in order to prevent much bloodshed. One day the leader of White Lotus Sect sent an invitation to Dragon and Master Huang but Dragon''s disciples saw this as a trap and recommended that they wait for Master Huang, who was out of town collecting medicine. The Master did not want to miss this opportunity to make peace and went alone. Unfortunately, he was captured and put in prison. Both parties started confrontations and have struggled since then. Now dangers are hidden all over the place. Who is capable of resolving the situation? Let''s find out!' FROM games WHERE igdb_id = 39386 ON CONFLICT (game_id, language_code) DO NOTHING;
