INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Tennis', 'All of your favorite characters hit the court in a wild and wacky multiplayer tennis game from the makers of Mario Golf. Mario, Luigi, Bowser, Peach, Toad, and Donkey Kong lead off the all-star, 14-player line-up. The fast-paced action will have you unleashing vicious volleys, life-saving lobs, ballistic backhands and electrifying super-charged smashes!' FROM games WHERE igdb_id = 3406 ON CONFLICT (game_id, language_code) DO NOTHING;
