INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tomb-raider-level-editor', 130808, '2000-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7u80.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tomb Raider Level Editor', 'The level editor is the in-house tool used by the original Tomb Raider development team, Core Design, to produce levels for Tomb Raider. It was initially bundled with Tomb Raider: Chronicles (PC edition) in 2000, then also made available for download with extra assets. Commonly abbreviated to "TRLE", it enables the creation of levels within the Tomb Raider: The Last Revelation game engine. It is preloaded project files and their assets, among them an exclusive original level and several example levels from The Last Revelation. The included manual teaches the user how to recreate the exclusive level "Playable Tutorial Level".' FROM games WHERE igdb_id = 130808 ON CONFLICT (game_id, language_code) DO NOTHING;
