INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Elan Plus', 'Élan plus is a renewed version of Élan, a simulation game in which the player ''s objective is to be chosen as a crew on a crew exploration vehicle heading to Planet Elan. New features include scenarios and a Gallery Mode which allows you to view event graphics after clearing stages. But it all depends on you whether you can make it to Planet Elan. It adds scenario corrections, new graphics, gallery mode, in game load, and reset functions.' FROM games WHERE igdb_id = 166161 ON CONFLICT (game_id, language_code) DO NOTHING;
