INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('redcat-spookkasteel--1', 212738, '2000-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co527q.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RedCat Spookkasteel', 'Grizella, the wicked witch, has captured WhizzKitty and only RedCat can save her! RedCat must search in and around the magical haunted castle. RedCat will have to face numerous enemies in five different worlds. In the forest, the castle, the caves, the graveyard, and the castle tower, Brutus and Max are also hiding and will try to thwart RedCat at the most unexpected times! Along the way, RedCat will encounter creepy and enchanted creatures such as giant spiders, red-nosed bats, poison frogs, and brightly colored ghosts!' FROM games WHERE igdb_id = 212738 ON CONFLICT (game_id, language_code) DO NOTHING;
