INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('iss-pro-evolution-2', 18681, '2000-08-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5u87.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/vj5zp0fl4grfnm5av5gj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ISS Pro Evolution 2', 'ISS Pro Evolution 2 (known as World Soccer Jikkyou Winning Eleven 2000: U-23 Medal he no Chousen in Japan) is the fourth video game in the ISS Pro series and the second instalment of the ISS Pro Evolution series. It was developed exclusively for the PlayStation by Konami Computer Entertainment Tokyo. It was available in Europe and Japan but not North America, as ESPN MLS GameNight was released in that territory instead. It is the first ISS Pro game with proper licenses, although partial, with some players having real names. The game has an extended Master League, with two divisions and eight more clubs, resulting in twenty-four club teams, such as Leeds United and Boca Juniors. More international teams were added as well. The gameplay also changed, becoming smoother and more realistic. The Japanese version of the game also contains Under-23 National Teams, which are not present in the European versions of the game.' FROM games WHERE igdb_id = 18681 ON CONFLICT (game_id, language_code) DO NOTHING;
