INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rent-a-hero-no-1', 6002, '2000-05-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2xaa.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar7px.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rent-A-Hero No. 1', 'Rent A Hero No. 1, a remake of the original Mega Drive game, was released for the Dreamcast in 2000. It features similar events to Rent A Hero, this time adding Rent A Hiroko, a female counterpart of Taro. The fighting engine used for the game is the same used for Sega''s Spikeout games and allows the player to receive hints via in-game email. The game was enhanced and given online capabilities by Coolnet Entertainment for the Xbox in 2003, and also translated into English for a North American release in what would have been the first Rent A Hero overseas release. However, the English version of the game was never released due to distribution problems, and the Xbox version remained only in Japan as had previously happened with the original Dreamcast version. In 2008, the unreleased English-translated version of the game got leaked and appeared on torrent sites in an apparently complete state, with only minor text errors present. This version was very close to completion and was reviewed by GamePro and Electronics Gaming Monthly in February 2003.' FROM games WHERE igdb_id = 6002 ON CONFLICT (game_id, language_code) DO NOTHING;
