INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wario Land 3', 'Trapped inside a magical music box, the invincible Wario is on a dangerous quest to help a mysterious figure recover its lost powers! Smash, bash and crash your way through more than two dozen gigantic levels in search of hidden keys, valuable treasures and mystical music boxes. Test your wits on puzzle after intricate puzzle and flex your muscles in action-packed boss fights! Be wary of Wanderin'' Gooms, Hammer-bots, Mad Scienstein and more as you plunge into one of the largest, most dazzling adventures ever to hit Game Boy Color!' FROM games WHERE igdb_id = 1698 ON CONFLICT (game_id, language_code) DO NOTHING;
