INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Diva Starz', 'Discover the secrets of the Diva Starz on a mall adventure with the four ultra-hip talking teens! Get to know the Diva Starz--the hottest teen friends around--on an awesome adventure at the mall! Visit the Divas'' favorite hangouts, try on all kinds of Diva-a-licious outfits, mix new music tunes, and create Cute-errific hairstyles. You can even hit the arcade and go for the high score! Take the Diva Challenge to figure out what each Diva likes best, and she''ll reveal her deepest secrets and share some special surprises.' FROM games WHERE igdb_id = 71601 ON CONFLICT (game_id, language_code) DO NOTHING;
