INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shadow Watch', 'Congratulations, Soldier, You''ve been recruited to lead an elite corporate commando squad.  As chief of security, it''s your job to stop a deadly plot to destroy the construction of the world''s first international space station.  There''s no end to the adventure, or the danger, when you step into the shadows.' FROM games WHERE igdb_id = 1860 ON CONFLICT (game_id, language_code) DO NOTHING;
