INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gauntlet-legends--3', 322269, '2000-06-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co91oe.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scugcn.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gauntlet Legends', 'The third and final console version of Gauntlet Legends, released in June of 2000. This version is most notable for being a near-direct arcade port, as the only console port to feature the four original Realms from the arcade original. However, some of their levels were completely redone, a new physics engine was used, and some of the soundtracks were remixed. Like the arcade version, there is no inventory. The player can only access the shop after completing a level. Special items are used on a time limit, which is slightly longer than the arcade version. The game is often criticized for not allowing players to buy food at the shop. This port includes many features from Gauntlet: Dark Legacy, including its 8 new character classes. The Poisoned Fields area is included as the first level in the Castle Stronghold. The Mausoleum is also accessible from a secret passage in the Castle Courtyard.' FROM games WHERE igdb_id = 322269 ON CONFLICT (game_id, language_code) DO NOTHING;
