INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Baldur''s Gate II: Shadows of Amn - Collectors'' Edition', 'Baldur''s Gate II: Collector''s Edition includes four custom CD-ROMs, featuring the complete Baldur''s Gate II: Shadows of Amn in a jewel case. Additionally, the Collector''s Edition features a special bonus disc containing exclusive weapons and armor as well as tracks from the original game soundtrack; a cloth map displaying the Kingdom of Amn in vivid color; a set of eight collectible Character Trading Cards (one of two sets randomly distributed, 16 trading cards in all); and a Black Isle Studios writing tablet, all appropriately ensconced in a hinged, book-style serialized box.' FROM games WHERE igdb_id = 91241 ON CONFLICT (game_id, language_code) DO NOTHING;
