INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-bust-a-move', 6618, '2000-09-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5v2w.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scng6t.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Bust-A-Move', 'Super Bust-A-Move introduces some new elements to the series (and removes some others): Large bubbles are found in certain levels. Shooting a bubble of the same color at them makes every bubble in the level change into that color. In some levels, the pointer and the bubbles that are shot are of a very small size, enabling the player to shoot bubbles between small gaps. These bubbles grow into normal size after being clustered. Occasionally, a conveyor belt will surround the level. This makes bouncing off the ceiling and the walls significantly tricky, since the bubbles'' trajectory will change upon bouncing. Levels do not always have the usual rectangular shape. Some of them are jagged or have walls inside them, which forces the player to change strategy. Small blocks appear in some levels. They change the bubbles'' trajectories, much like walls, but they move down with the level and fall off when they touch the line. The pulley system introduced in Puzzle Bobble 4 is nowhere to be seen. Chain Reaction is only present in 2P battles, but it is completely optional.' FROM games WHERE igdb_id = 6618 ON CONFLICT (game_id, language_code) DO NOTHING;
