INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gogo-i-land', 344573, '2000-12-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9u76.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scyk9p.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gogo I-Land', 'You play the role of a active manager of a production company. One day your boss orders you to go out and find the "star of tomorrow." So you go to a talent development institution called Twinkle Actress School. Your job is to sneak into there undercover and find potential candidates. The only person there who knows your true identity is your ex-trainee Sanae who is now the dorm director. Besides her, there are 5 girls that catch your attention: Nozomi who is Sanae''s niece, Mayu who is the sister of a really famous star, Hiziri whose voice can make her a famous singer, Shizuya who has a great potential to be a beautiful model, and Mamiko who is talented in voice acting. You will stay for 3 weeks, and during your stay you will take lessons with girls and communicate with them and get as much data as possible so you can report to your boss.' FROM games WHERE igdb_id = 344573 ON CONFLICT (game_id, language_code) DO NOTHING;
