INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('superlite-1500-series-qix-2000', 97320, '2000-10-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob4m0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4zsl.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SuperLite 1500 Series: Qix 2000', 'Qix 2000 offers both a perfectly-translated version of the original and the insanely fun arrangement version, which updates the graphics (giving the Qix itself a Tempest X3-style psychedelic flair) and adds a few power-ups to the mix. The speed-up power-up makes even slow draw fast, and fast draw faster, but the speed-down power-up negates that effect - and heaven help you if you hit the latter while already operating at normal speed.' FROM games WHERE igdb_id = 97320 ON CONFLICT (game_id, language_code) DO NOTHING;
