INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kessen', 10092, '2000-03-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1ow7.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kessen', 'The ancient storied battlefield lies before you. At your command are 100,000 troops including archers, infantry, riflemen, and the powerful cavalry. Kessenis a real time strategy game that gives players strategic command and control over huge armies during epic battle sequences from the Warring States period of seventeenth century Japan. Key features include more than 100 movie segments, battlefields with full 3D terrain, separate animation routines for every character, and three different camera views. Known best because it is the very first PlayStation 2 game to ship using the DVD format.' FROM games WHERE igdb_id = 10092 ON CONFLICT (game_id, language_code) DO NOTHING;
