INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bust-a-move-millennium', 49836, '2000-10-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9kod.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scvulx.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bust-A-Move Millennium', 'BUST-A-MOVE MILENNIUM EDITION on Game Boy Color brings a bevy of often-requested new features to this classic puzzler. Bubbles of different colors descend from the top of the screen in clumps. Using your blaster that fires colored bubbles of your own, you must attempt to clear the screen as best as you can. BUST-A-MOVE MILENNIUM EDITION offers five unique modes of play. In the returning Puzzle mode, you''ll play through a huge number of new stages of bubble-busting action that require careful planning and fast reflexes. Challenge mode also returns to test your BUST-A-MOVE skills. In the brand new Story mode, you''ll take on a series of increasingly difficult computer opponents in a battle to the finish. Also new is a mode that allows you to play as long as you can last. Of course, the biggest and best addition to BUST-A-MOVE MILENNIUM EDITION is the two-player link cable Versus mode. Now you can grab a friend and show off your BUST-A-MOVE skills! You get all of this plus enhanced graphics and other new options.' FROM games WHERE igdb_id = 49836 ON CONFLICT (game_id, language_code) DO NOTHING;
