INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('supercross', 44949, '2000-12-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/j0aa3v1py5tsovk54ec8.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Supercross', 'Supercross features a more action-oriented style of gameplay. Tricks are smoother and may come a little more easily, but players will still have to hold the right line and perfect their timing if they''re going to be real contenders in the Motocross circuit. Players will race through several indoor and outdoor tracks in this dirt bike simulation from EA SPORTS, and a freestyle mode is available as well, offering a perfect track for maximum air and wild tricks.  The most notable change in Supercross is that EA opted to go with a more arcade-styled control scheme this time around. While this may come as a disappointment to gamers looking for the ultimate motocross sim, fact of the matter is, they tried the more realistic approach in the last game and it did not work well. Besides, with this game''s new hold-the-accelerator-and-don''t-let-go approach, gamers will get a better sense of the speed they would experience in they actually participated in a motocross event.  The game is known in usa as Supercross 2001' FROM games WHERE igdb_id = 44949 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 44949 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
