INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('popn-music-5', 78971, '2000-11-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2bb7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8ddn.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pop''n music 5', 'Pop''n music 5 is a rhythm game. It is the 5th game in the Pop''n Music series and a part of Konami''s BEMANI Franchise. The game is played on a controller with 9 large coloured buttons, each button has a lane representation on the screen, along each lane similarly coloured icons (called pop-kun) move down the screen, when they reach the judgement line the player must press the corresponding button with correct timing. pop''n music 5 is the first game in the series to have Internet Ranking, where a code is generated after play that can be submitted to Konamis leaderboards. It is also the first apperance of the difficulty level EX, which could only be played on EXtra stages. All songs from before pop''n music 4 are not returning for this game. 25 songs returns from pop''n music 4 and are joined by 30 new songs for a total of 55 songs.' FROM games WHERE igdb_id = 78971 ON CONFLICT (game_id, language_code) DO NOTHING;
