INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cool Cool Jam', 'Cool Cool Jam is a instrumental rhythmic game developed by SNK for the Neo Geo Pocket Color. It is was released in August 10, 2000 alongside with Cool Cool Toon. The game was never released outside Japan, although an English sample was produced for reviewers, meaning SNK considered a possible release in the US/EU market.' FROM games WHERE igdb_id = 43967 ON CONFLICT (game_id, language_code) DO NOTHING;
