INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('virtual-pro-wrestling-2-oudou-keishou', 3625, '2000-01-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/tucrem7ud9pqmtee2wd9.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Virtual Pro Wrestling 2: Oudou Keishou', 'The sequel to Virtual Pro Wrestling 64, and released only in Japan. The title translates to Royal Road Succession; the name of the career mode in the game. The fifth wrestling game developed by AKI Corporation. Contained many improvements from previous titles that would be featured in AKI''s final Nintendo 64 wrestling game WWF No Mercy. Some features, such as creating masks in edit mode and the MMA style grappling system, would not be carried over to WWF No Mercy. Virtual Pro Wrestling 2 carries the All Japan Pro Wrestling license, and features 21 wrestlers from their promotion. The rest of the characters included in the game are based on other real promotions and wrestlers, but due to copyright have fake names and appearances. This is common among other Japanese wrestling games. You can identify who the other wrestler''s are by their unique moves and taunts, and the edit mode contains each piece of ring attire you would need to recreate their actual likeness. In total, there are 98 wrestlers in the game, 23 of which have to be unlocked. There is also 16 original character slots you can use to edit and create your own wrestlers, bringing the potential total of wrestlers in the game to 114. This game has the largest roster of all of AKI''s wrestling games. In comparison, WWF No Mercy would have 64 wrestlers available.' FROM games WHERE igdb_id = 3625 ON CONFLICT (game_id, language_code) DO NOTHING;
