INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pinchcliffe Grand Prix', 'Pinchcliffe Grand Prix - The PC Game is the biggest game success in Norway of all time. It features activities and animations for hours and hours of entertainment for all the family. Gamers get to repair bicycles, do jigsaws, feed birds, ride Sonny''s trike, paint, catch butterflies and sort socks! Along the way, they find or win car parts enabling them to build Il Tempo Gigante, no less - and take part in the car race itself. The game has won the EMMA Award in the Entertainment Category.' FROM games WHERE igdb_id = 54663 ON CONFLICT (game_id, language_code) DO NOTHING;
