INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Golem no Maigo', 'A Dreamcast puzzler developed mostly by one Japanese student, Golem no Maigo (also known by its English translation "The Lost Golem") tasks you with guiding the king to the end of every stage by pushing walls around while also ensuring there are enough walls that remain intact to progress.' FROM games WHERE igdb_id = 64705 ON CONFLICT (game_id, language_code) DO NOTHING;
