INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metal Gear: Ghost Babel', 'Metal Gear: Ghost Babel is a Game Boy Color spinoff of the popular stealth action game Metal Gear Solid. This is not a port of said game but an original game made specifically for the Game Boy Color. Metal Gear: Ghost Babel is a non-canon game that serves as an alternate sequel to the events of the original Metal Gear.' FROM games WHERE igdb_id = 5600 ON CONFLICT (game_id, language_code) DO NOTHING;
