INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Avernum 2', 'Taking place five years after the events of the first Avernum, this game follows its party of characters fighting back against military forces being sent down to Avernum by the Empire and investigating the source of mysterious energy barriers that have begun appearing.' FROM games WHERE igdb_id = 19581 ON CONFLICT (game_id, language_code) DO NOTHING;
