INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('caesars-palace-2000-millennium-gold-edition', 45807, '2000-06-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2uqy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc94dz.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Caesars Palace 2000: Millennium Gold Edition', 'Now you can get all the action of Las Vegas without the smoky casinos in CAESARS PALACE 2000: Millennium Gold Edition. There are a variety of games to play including Blackjack, Mini-Baccarat, Paigow Poker, Spanish 21, Red Dog, Casino War, Roulette, Craps, Video Poker, Video Keno, Poker Challenge, and five different slot machines. All games are played according to the Vegas rules, giving you the most realistic experience you can get this side of Nevada. Things are so authentic in this virtual casino that the slot machines even have the faces of their real-world counterparts. There is also an intuitive interface that allows you to utilize even the most complex betting strategies with ease. So get the Vegas experience without draining your savings account with CAESARS PALACE 2000: Millennium Gold Edition.' FROM games WHERE igdb_id = 45807 ON CONFLICT (game_id, language_code) DO NOTHING;
