INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Police 911', 'An arcade light-gun shooter with a camera to detect player movement, allowing the player to use body movement to hide behind cover and dodge the (slow-moving) bullets. It was the first video game with fairly accurate full-body motion detection, and probably the only one with a motion-controlled cover system.' FROM games WHERE igdb_id = 77016 ON CONFLICT (game_id, language_code) DO NOTHING;
