INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('k-1-grand-prix', 43722, '2000-02-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/hlsabtpq8jyfwd4vwwhw.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'K-1 Grand Prix', 'The rough and tumble world of professional kickboxing comes to the PlayStation with K-1 Grand Prix. Choose from 16 professional kickboxers including Andy Hug, Musashi, and Ernesto Hoost, and if you don''t like any of the professional contenders, create your own. After choosing the right avatar, jump into the ring for some training. Once you are ready for some competition, you can try to win a Tournament, but those players looking for a real challenge should play the Career mode. This is where you try to work your way from the bottom of the rankings to the championship. Between each bout, spend time training; how well you perform each training task will reward you with points that can be spent on new moves and combinations. Do you have the grit and determination to become the best in K-1 Grand Prix?' FROM games WHERE igdb_id = 43722 ON CONFLICT (game_id, language_code) DO NOTHING;
