INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dance-dance-revolution-4thmix-plus', 135393, '2000-12-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5u5i.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8czs.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dance Dance Revolution 4thMix Plus', 'Dance Dance Revolution 4thMix Plus is an upgrade of 4thMix, released on December 28, 2000. It adds fourteen new songs not seen in any previous DDR version. Several older songs have received new Maniac step sets, with the old steps being moved to "Maniac-S" (for Single) or "Maniac-D" (for Double). The new steps are generally much harder than before, and are used as the default Maniac steps in Dance Dance Revolution 5thMix. The old step sets have been restored for songs included in DDRMAX2 Dance Dance Revolution 7thMix, and certain 4thMix Plus steps return as Challenge steps in Dance Dance Revolution Extreme. An all music mode feature is included for Dance Dance Revolution 4thMix Plus where players have access to all songs in the game instead of picking music genres' FROM games WHERE igdb_id = 135393 ON CONFLICT (game_id, language_code) DO NOTHING;
