INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Freedom: First Resistance', 'Freedom: First Resistance is a third-person action-adventure game set in a future where Earth has been invaded by the alien Catteni race. Players take on the role of Angel Sanchez, a human resistance leader, and lead a team of rebels against the oppressive alien regime. The game features stealth-based gameplay, puzzle-solving, and strategic use of different team members to overcome challenges and liberate humanity' FROM games WHERE igdb_id = 1862 ON CONFLICT (game_id, language_code) DO NOTHING;
