INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dave Mirra Freestyle BMX', 'Dave Mirra Freestyle BMX is a video game released in 2000 featuring BMX Rider Dave Mirra and other professional BMX riders. It was developed by Z-Axis Ltd. and published by Acclaim Entertainment under their Acclaim Max Sports label. The game was released on the PlayStation, Game Boy Color, Dreamcast and Microsoft Windows. The player''s main objective in the game is to choose one of the riders and work their way through a total of 12 different levels, completing objectives to unlock new equipment. A sequel was released in 2001 entitled Dave Mirra Freestyle BMX 2.' FROM games WHERE igdb_id = 26012 ON CONFLICT (game_id, language_code) DO NOTHING;
