INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blue Submarine No. 6: Time and Tide', 'Blue Submarine No. 6: Time And Tide is an underwater-exploration game developed by Sega and released for the Dreamcast in 2000. The game follows the exploits of a deep-sea salvage crew as they recover treasure. The game includes FMV animation by Gonzo, a renowned Anime studio responsible for the original OVA.' FROM games WHERE igdb_id = 66288 ON CONFLICT (game_id, language_code) DO NOTHING;
