INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kisha de GO!', 'Kisha de Go! is an offshoot of the Densha de Go! series. This version of the game allows players to drive a steam train, rather than an electric train like the other entries. The coverage included portions of the Keihin-Tōhoku Line, Shin''etsu Main Line and Ban''etsu-Sai Line. The controls were made slightly more complex to reflect steam operation.' FROM games WHERE igdb_id = 63754 ON CONFLICT (game_id, language_code) DO NOTHING;
