INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oz: The Magical Adventure', 'A children''s interactive story computer game that is loosely based on The Wonderful Wizard of Oz. It has three reading levels of text to choose from as the player progresses through the story and plays some mini-games while interacting with the scenery. The game''s release in 2000 celebrates 100 years since the publication of Baum''s book.' FROM games WHERE igdb_id = 78998 ON CONFLICT (game_id, language_code) DO NOTHING;
