INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('elasto-mania', 9103, '2000-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co27s6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar144g.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Elasto Mania', 'Elasto Mania (also known as Elma) is a physics-simulation game released in 2000. It claims to be "based on a real physical model." It explores the notion of elastic motorcycles. The goal of each level is to collect every apple (disappearing by contact) spread throughout it, and then to touch the flower (the exit object). Some people, especially the ones part of online groups such as Mopolauta, play the game trying to finish levels as fast as possible, while others, mostly quite-new-to-the-game players, simply concern themselves with the accomplishment of levels, often first requiring figuring out a way for them to be solved. Ultimately, though, experienced players are motivated by the objective of finishing levels in the least amount of time possible, trying either to settle down personal, or world, records. That contributes to setting the stage for serious competition, especially in the official game levels.' FROM games WHERE igdb_id = 9103 ON CONFLICT (game_id, language_code) DO NOTHING;
