INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Polaris SnoCross', 'If it doesn''t say Polaris... it ain''t SnoCross! Join the Polaris Snowmobile Racing Team and dare to tame the mountain! Pull off a variety of insane tricks as you master the challenges of monster jumps, hidden pitfalls, shortcuts, and treacherous terrain. Race against fiercely competitive AI characters, or take on your own friends in multi-player mode. Feel your customized Polaris sled move, twist and turn just like a real snowmobile!' FROM games WHERE igdb_id = 3575 ON CONFLICT (game_id, language_code) DO NOTHING;
