INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Autobahn Raser III', 'Autobahn Raser III is the third installment of Davilex'' Autobahn Raser series. Like in previous installments the player races through various German cities and on parts of the German Autobahn. New to this game is the addition of the story character Krüger, a police agent chasing down the Autobahn Raser club.' FROM games WHERE igdb_id = 210277 ON CONFLICT (game_id, language_code) DO NOTHING;
