INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster Rancher Hop-A-Bout', 'Monster Rancher Hop-A-Bout is a platform adventure game based on characters from the Monster Rancher video games and animated TV series. Hop-A-Bout is an addictive and easy-to-learn title that challenges players to hop their way through more than a hundred obstacle courses.' FROM games WHERE igdb_id = 78298 ON CONFLICT (game_id, language_code) DO NOTHING;
