INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pocket Monster', 'Pocket Monster is an unlicensed platformer based off the Pokémon series for the Mega Drive and SNES. Like the Famicom pirate, players control Pikachu through numerous side-scrolling levels with a boss at the end of each. Although some of the enemies encountered are Pokémon such as Beedrill, Porygon and Diglett, the others are taken from Magical Taluluto-kun, Syd of Valis, and Super Metroid with different palettes.' FROM games WHERE igdb_id = 45692 ON CONFLICT (game_id, language_code) DO NOTHING;
