INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kyojin no Doshin Kaihou Sensen Chibikko Chikko Daishuugou', 'Kyojin no Doshin Kaihou Sensen Chibikko Chikko Daishuugou is a game for the Nintendo 64DD, and a successor to Doshin the Giant 1. It was one of the games which supported the Randnet online service. A game in which Doshin is imprisoned. Switching between this game and Doshin the Giant 1, the player must, as before, build various monuments. Special movies are unlocked while playing the game.' FROM games WHERE igdb_id = 72278 ON CONFLICT (game_id, language_code) DO NOTHING;
