INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mayday: Conflict Earth', 'A real-time strategy game. Players select one of the factions and commands an entirely mechanized army, which includes automatized tanks, cyborgs, and other non-human personnel. There is no resource harvesting in the game, and money is awarded gradually as the player completes missions. There is also no construction, with the buildings already available, requiring the player only to assign their position on the map.' FROM games WHERE igdb_id = 36932 ON CONFLICT (game_id, language_code) DO NOTHING;
