INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bugs-bunny-in-crazy-castle-4', 8724, '2000-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3b6n.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/zu1mwszxppsdvgi5or2h.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bugs Bunny in Crazy Castle 4', 'Bugs Bunny returns in BUGS BUNNYS CRAZY CASTLE 4 for Game Boy Color! Thinking he has found the Carrot Castle, Bugs has once again entered the Crazy Castle. You must help him escape in this single-player action or puzzle game. This time, more than 60 rooms await Bugs, and he''ll have to use all of his wits and skills to escape with his "hare" intact. Once again, the Crazy Castle is loaded with traps and hazards that will cut your carrot-collecting career short so make sure you don''t get reacquainted with them the hard way. As CRAZY CASTLE fans are probably used to, several Warner Bros. cartoon characters are here to keep Bugs on his toes. You''ll have to fight off Daffy Duck, Yosemite Sam, Foghorn Leghorn, Pepe Le Pew, Tweety, and the Tazmanian Devil with one of a variety of weapons, or make tracks to the nearest safe spot. A password save will chart your progress so that you don''t have to start from scratch each time you play.' FROM games WHERE igdb_id = 8724 ON CONFLICT (game_id, language_code) DO NOTHING;
