INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nige-ron-pa', 43961, '2000-11-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co92vk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scuk2v.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nige-ron-pa', 'nige-ron-pa is a turn-based RPG set in the world the game was named after featuring humans, elves, demons and other creatures co-existing with each other. Players take control of an elf and a catgirl who are about to take the exam and become workers. After passing the exam and obtaining a license, players can accept various tasks which will reward them with money and Worker points. The worker points serve both as the game''s reputation system and are an integral part of the game''s license system. They determine who would accept to be a part of the player''s party, as well as allow players to get new licenses, which works in a similar way to Final Fantasy''s job system. Equipping different licenses will unlock different spells for players to use in battle. The more worker points players get, the more likely it is that additional characters can be hired.' FROM games WHERE igdb_id = 43961 ON CONFLICT (game_id, language_code) DO NOTHING;
