INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kids Station: Soreike! Anpanman', 'Soreike Anpanman (written by Takashi Yanase, a Japanese writer of children''s stories, is one of the most popular anime cartoon series in Japan. It is produced by Nippon Television Network Corporation. The Playstation game is a collection of mini games in witch you control Anpanman in different kind of situations.' FROM games WHERE igdb_id = 302606 ON CONFLICT (game_id, language_code) DO NOTHING;
