INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Robot Taisen Alpha', 'Super Robot Taisen Alpha is the second game in the series to be built from the ground up for the Playstation, and is the start of the Alpha series. Alpha is the first SRW to feature the highly choreographed animation that the series is known for.' FROM games WHERE igdb_id = 72841 ON CONFLICT (game_id, language_code) DO NOTHING;
