INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jahmong', 'Jahmong is a Sega Dreamcast online mahjong game developed and published by Visit. Released exclusively in Japan in August 2000, Voice recognition mahjong game. It''s a hot game with a voice recognition system like never before, with increased luck depending on the size of your voice. Play against strong enemies all over the country at Gourmet Mode. From Hokkaido in the north to Kyushu in the south, around the country, get all the local specialties!!' FROM games WHERE igdb_id = 327412 ON CONFLICT (game_id, language_code) DO NOTHING;
