INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kids Station: Hello Kitty no Oshaberi Town', 'Hello Kitty no Oshaberi Town is a collection of 16 mini games where the players can learn about colors, numbers, sounds, animals, etc. The mini games go from paint a drawing, buy items at the market, clean the room, catch butterflies, set the clock time, etc. There are some 2 player mini-games as well.' FROM games WHERE igdb_id = 200556 ON CONFLICT (game_id, language_code) DO NOTHING;
