INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Umihara Kawase: Shun - Second Edition', 'The second edition of Umihara Kawase: Shun was launched almost three years after original release at a lower price as part of the Maruan series. This release contains five additional fields taking the total to fifty five. The game''s cut-scenes have been replaced with scrollable, static art of the protagonist, however, due to the removal of all Mitchell branding.' FROM games WHERE igdb_id = 78719 ON CONFLICT (game_id, language_code) DO NOTHING;
