INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mega Man Legends 2', 'Mega Man, Roll, and all your favorites are back in this all new 3-D adventure! Far away, in an isolated wasteland, a mysterious girl and an infamous treasure have been discovered. It''s the legendary "Sealed Key," rumored to unlock an even greater mystery known as the Great Legacy. What power does the Great Legacy hold? Now, a raced unfolds as Mega Man and his friends embark on a journey which will alter their destinies forever.' FROM games WHERE igdb_id = 1754 ON CONFLICT (game_id, language_code) DO NOTHING;
