INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Evil Dead: Hail to the King', 'Hail to the King was developed by Heavy Iron Studios and published by THQ. The game featured familiar locales such as the cabin and the woods. The game expaneds with new locations such a nearby town, cemetary, and Ash even gets to travel back in time to the middle ages. Hail to the King also features familiar characters from the films and includes the voiceover and new witty one-liners of Bruce Campbell.' FROM games WHERE igdb_id = 47078 ON CONFLICT (game_id, language_code) DO NOTHING;
