INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Romance of the Three Kingdoms VII', 'Romance of the Three Kingdoms VII, the seventh title of the series, invites you to live your own Three Kingdoms experience. You will travel back to ancient China and play as any of 535 possible characters. Features new to this installment include multiplayer modes and quicker gameplay. The game has 10 scenarios, each with multiple endings.' FROM games WHERE igdb_id = 7254 ON CONFLICT (game_id, language_code) DO NOTHING;
