INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('extreme-sports-with-the-berenstain-bears', 49932, '2000-12-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/vf5avgldle3gqzmf7ivp.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Extreme Sports with the Berenstain Bears', 'Get extreme with Mama, Papa, Brother, and Sister Bear in their first Game Boy Color game, EXTREME SPORTS WITH THE BERENSTAIN BEARS! In this single-player game you''ll control the members of the family as they participate in an assortment of extreme sports events. Use Brother or Sister Bear in kayaking, dirt boarding, biking, and luge, or take the whole family in the river rafting and toboggan sequences. All of the events take place from an overhead perspective, which provides the best view of the playing field. In each event you can perform a wild range of tricks and stunts to gain speed and shave seconds off the clock. Can you beat the high scores and become the best bear you can be? Well-animated characters set on colorful, detailed backgrounds ensure a bright presentation.' FROM games WHERE igdb_id = 49932 ON CONFLICT (game_id, language_code) DO NOTHING;
