INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ski-air-mix', 186129, '2000-09-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4bb4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scf3r7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ski Air Mix', 'Ski Air Mix is a ski game that features 4 different characters (that can be customized) and skis. In the game the goal is to be the fastest in reach the goal. The game features 3D graphics and different circuits and even a vs mode against the computer or another player. Master the wildest international ski slopes with the help of 4 player characters and 11 different pairs of skis. Alpen or Versus Modes allow you to challenge the computer or a friend as you race towards the bottom of the 5 slopes. Perform wild stunts and speed compete simultaneously in this great futuristic board game.' FROM games WHERE igdb_id = 186129 ON CONFLICT (game_id, language_code) DO NOTHING;
