INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tomb Raider Starring Lara Croft', 'Tomb Raider is an action-adventure video game released for the Game Boy Color. This release is significant as it is the first portable game in the Tomb Raider series. This version has the standard Tomb Raider gameplay of running, jumping and switch-flipping, but presented in a side-view 2D style, reminiscent of Flashback. At Lara''s disposal are 25 or so moves, which are crammed onto the 2 GBC buttons. There are also game-save crystals at special points throughout the levels. Although it shares its title with the first entry in the series, Tomb Raider for Game Boy Color follows a different storyline.' FROM games WHERE igdb_id = 36878 ON CONFLICT (game_id, language_code) DO NOTHING;
