INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('10six-online', 94316, '2000-02-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2xag.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar7q1.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '10Six Online', '10Six is a massively multiplayer online strategy game developed by Segasoft and published by Sega for Windows PCs. 10Six was Sega''s first foray into MMO''s, a persistent online RTS where players signed up for one of four mega-corporations aiming to conquer the rogue planet Visitor, which has entered the solar system and contains a treasure of valuable resources. Players construct and capture mining sites, construct defenses and NPC units to help defend and attack in a fairly traditional RTS mode, but much of the game also consists of player on player combat in first or third person modes, similar to Battlezone or Planetside. The server infrastructure was designed to be able to handle a million simultaneous players and was hosted through SegaSoft''s Heat.net (and later 10SIX.com), but never saw player counts that high. After failing to attract a sufficiently large audience Sega shut down the game in June 2002, offering refunds to anybody with subscription time left. It was set to be ported to the Sega Dreamcast, originally for Autumn 2000 but was delayed and then cancelled in March 2001. A community effort to relaunch the game was started soon after the servers were taken down. Conundrum Studios was formed in late 2002, and the game was relaunched under the name Project Visitor in 2003.' FROM games WHERE igdb_id = 94316 ON CONFLICT (game_id, language_code) DO NOTHING;
