INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Allegiance', 'Allegiance is a multiplayer space combat sim originally developed by Microsoft that offers the action of ship-to-ship combat. From small, agile scouts to massive destroyers, you not only fly but also man the turrets. With real-time strategy components such as fully upgradeable tech and massive multiplayer capability, Allegiance stands at the forefront of online interstellar combat.' FROM games WHERE igdb_id = 595 ON CONFLICT (game_id, language_code) DO NOTHING;
