INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spectrum 2000', 'A vertical scrolling jet shoot them up, featuring both single & co-operative gameplay as well as a myriad of power ups. The players get to choose from 5 different jets each with it''s own unique attributes & weapons. By collecting varies power ups during the missions the player''s jet with be transformed into a stronger, more powerful version.Best video game consoles' FROM games WHERE igdb_id = 382668 ON CONFLICT (game_id, language_code) DO NOTHING;
