INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tiger Woods PGA Tour 2001', 'Swing into action with the first-ever PS2 golf game from Electronic Arts in Tiger Woods PGA Tour 2001. In all, six pro golfers take to the green on three real-life courses including SpyGlass Hill, Pebble Beach, and Poppy Hills as they swing and putt their way through exact replicas of all 18 holes. The varied modes of play are now supported by two new entries, Challenge and Play-Now, in addition to such returning staples as Match, Skins, and Stroke.' FROM games WHERE igdb_id = 8812 ON CONFLICT (game_id, language_code) DO NOTHING;
