INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('speedball-2100', 10153, '2000-09-01', 40, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co303d.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar8og.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Speedball 2100', 'This 32-bit update to the original Speedball is best described as a futuristic combination of hockey and rollerball. Speedball 2100 pits two teams of nine players in a cage-like arena where they attempt to score by sending a steel ball past the goalie and into the small goal box. You can bounce the ball off the walls, and you can send opponents flying to the floor with a friendly shoulder charge. Fans of the predecessor will appreciate this sequel. Speedball 2100, released only for the PlayStation, is a 3D version of Speedball 2 with more options such as choosing and renaming any team, instead of having to play with Brutal Deluxe. This version, released in September 2000, failed to win over gamers and press because it lacked the speed and gameplay of the originals. Speedball 2100 will be released on Evercade as part of the Bitmap Brothers Collection 1.' FROM games WHERE igdb_id = 10153 ON CONFLICT (game_id, language_code) DO NOTHING;
