INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Reader Rabbit: I Can Read With Phonics', 'Reader Rabbit: I Can Read With Phonics (stylized as Reader Rabbit: I Can Read! With Phonics) is a 2-in-1 CD compilation released in 2000 by The Learning Company. The compilation features the games Reader Rabbit Reading Adventures Ages 6–9 (titled "Road to Imagination") and Reader Rabbit''s Reading 2 (titled "Wordville Station").' FROM games WHERE igdb_id = 366183 ON CONFLICT (game_id, language_code) DO NOTHING;
