INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 1500 Series Vol. 45: The Block Kuzushi 2', 'Block Kuzushi 2 is a good breakout game that can be played by 2 players in cooperative or VS mode. The game is the sequel to Block Kuzushi (released as Block Buster in Europe) and this one wasn''t released outside Japan. The game offers some interesting special moves like the one in which you can hit the ball with effect pressing a button.' FROM games WHERE igdb_id = 203030 ON CONFLICT (game_id, language_code) DO NOTHING;
