INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('star-wars-episode-i-jedi-power-battles', 6606, '2000-04-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coav0d.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar39bx.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: Episode I - Jedi Power Battles', 'The game follows the plot of Star Wars Episode I: The Phantom Menace. Players can choose from one of five prequel-era Jedi and run, jump, slash, and use the Force through the game''s ten levels, starting on the Trade Federation Battleship and ending with the battle against Darth Maul on Naboo. The player''s primary weapon is a lightsaber used to fight through waves of enemies and deflect blaster shots. The lightsaber combat is rather simplified with a system that lets the player lock on to the nearest enemy using the R1 button. Items and the force can also be used for special attacks. On most levels jumping puzzles make up a large portion of the challenge. There are a few segments in which the player can pilot various craft. The single player campaign can also be played in cooperative mode with a second player.' FROM games WHERE igdb_id = 6606 ON CONFLICT (game_id, language_code) DO NOTHING;
