INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s The Little Mermaid II: Pinball Frenzy', 'This game is basically Pokémon Pinball minus all the pokémon plus Ariel and her young daughter, Melody -- and a lot of minigames. The game features four-player support via alternating tables, as well as a battery-powered rumble feature for those who absolutely must feel every tilt and tumble of the table.' FROM games WHERE igdb_id = 49919 ON CONFLICT (game_id, language_code) DO NOTHING;
