INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bionic Commando: Elite Forces', 'You are the ultimate weapon. You are the perfect synthesis of human and machine - a Bionic Commando.Your latest mission - to rescue a fellow commando, Commando Joe - will take you deep into the heart of enemy territory. Use your Bionic Claw to grapple and swing through more than 20 levels of forest, deserts, mountains and futuristic cities Blast through dozens of unique with your Assault Rifle, Rocket Launcher and Flame Thrower as you seek to destroy the overlord Arturus, and save your homeland of Karinia from utter destruction.' FROM games WHERE igdb_id = 44077 ON CONFLICT (game_id, language_code) DO NOTHING;
