INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mr. Driller 2', 'Test your drill skills in Mr. Driller 2, a colorful puzzle game for the Game Boy Advance. In an effort to save the world from being buried under colored blocks, you must drill your way through a variety of intricate puzzles while avoiding enemies and obstacles. Based on the arcade version, the sequel to Mr. Driller features Mission Driller, Endless Driller, and Time Attack Driller modes, plus a two-player mode that lets you play against a friend via link cable.' FROM games WHERE igdb_id = 49260 ON CONFLICT (game_id, language_code) DO NOTHING;
