INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Pro Mahjong: Menkyo Minnaten', 'The Pro Mahjong - Menkyo Kaiden is a mahjong game that features 5 different boards, 2 game modes: - Tournament: Compete against different opponents advancing rounds. - Free Mode: Play mahjong games against 15 Japanese spies of the Japan Pro Mahjong Federation opponents. In the tournament domination mode, you can challenge the ranking certification exam at each rank.' FROM games WHERE igdb_id = 376643 ON CONFLICT (game_id, language_code) DO NOTHING;
