INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metal Slader Glory: Director''s Cut', 'In the year 2062, Earth-based mechanic Tadashi and his girlfriend discover a mech from a war eight years prior with an ominous message stored in its memory suggesting Earth is in danger. They travel to nearby space stations and colonies to investigate its origins. Featuring redrawn graphics, scenes that had been cut for lack of storage space, and different music than the original, the Director''s Cut of Metal Slader Glory was the final officially released game for the Super Famicom.' FROM games WHERE igdb_id = 38238 ON CONFLICT (game_id, language_code) DO NOTHING;
