INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blaster Master: Enemy Below', 'Jason, brave hero of yesteryear, is roused from retirement by the news that mutant lifeeorms, thought to have been long since destroyed, are once again on the move, hollowing out subterranean niches in the image of their old haunts. The decision to reactivate Sophia seems to Jason nothing more than an inevitability. Back into the cold once more... - Eight areas to explore, to find the keys and kill the sub human bosses - Use the tank’s suction system to drive up walls and along ceilings - Drive Sophia or go it alone with Jason.' FROM games WHERE igdb_id = 49840 ON CONFLICT (game_id, language_code) DO NOTHING;
