INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Excitebike 64', 'Experience extreme MX! You grind your way through the hairpin turn, a wall of mud exploding in your wake. Your next jump launches you into the air - you pull off a spectacular double no-footed can-can and become an instant legend! In Excitebike 64, you''ll find all the high-flying action, heart-stopping stunts and bone-jarring crashes of the extreme sport of motocross. It''ll set the daredevil inside you free. 20 stadium tracks and awesome outdoor courses - plus six different riders with six unique styles!' FROM games WHERE igdb_id = 3337 ON CONFLICT (game_id, language_code) DO NOTHING;
