INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'FantaVision', 'A fast and furious puzzle game taken to all new heights, FantaVision combines action, shooting, strategy, and puzzle solving in one unique package. Players can combine a wild assortment of flares and other special effects to create explosive chain reactions and then replay the aerial spectacular and vary the camera angle and weather conditions in any way they choose. Environments include cityscapes, amusement parks, and the outer reaches of deep space' FROM games WHERE igdb_id = 10392 ON CONFLICT (game_id, language_code) DO NOTHING;
