INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 1500 Series Vol. 31: The Sound Novel', 'Simple 1500 Series Vol. 31 - The Sound Novel is a first person adventure game in which the player starts the game driving with his girl in a car in a lonely highway, where they are stopped by a policeman that tells them about the strange place that they are in. The gameplay is the classic is a sound novel game, the game tells the story and in some places the place can decide which way he wants to continue it, depending of the player answers the game ending will be different, since the game features multiple endings.' FROM games WHERE igdb_id = 112548 ON CONFLICT (game_id, language_code) DO NOTHING;
