INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: Episode I - Battle for Naboo', 'Attention defenders of Naboo! The Trade Federation must be stopped! Storm through more than 15 missions over land, sea and space as your freedom fighters rally against the droid armies. Take control of 7 vehicles: the Naboo starfighter, Gian speeder, and new craft like the heavy STAP, Trade Federation gunboat and more. More than 15 missions: escape from Theed, search & destroy, sabotage, reconnaissance, convoy. Battle against Trade Federation droid starfighters, AATs, destroyer droids, battle droids. Change vehicles mid-mission through specially designated hangars.' FROM games WHERE igdb_id = 156 ON CONFLICT (game_id, language_code) DO NOTHING;
