INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Popira', 'A rhythm game where you bounce falling balls back to the beat using four buttons. Its unique feature is that if timing is poor, the notes fall again. Songs can be added via cartridges, which are shared with e-kara.' FROM games WHERE igdb_id = 392681 ON CONFLICT (game_id, language_code) DO NOTHING;
