INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jellyfish: The Healing Friend', 'Jellyfish: The Healing Friend lets the player follow the life and times of a deep depths jellyfish who moves by way of water propulsion. Learn about the life cycle of your nebulous charge in this simulation where you attempt to raise a wild sea creature. Moderate water temperature, a regular feeding schedule and other factors will all contribute to your success or failure.' FROM games WHERE igdb_id = 171854 ON CONFLICT (game_id, language_code) DO NOTHING;
