INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WWF SmackDown!', 'All the top WWF Superstars! Largest interactive backstage area ever! Most advanced season mode - Make decisions affecting rivalries, backstage story lines and tag teams. Revolutionary Create-a-Superstar - Sliding scales, movies, and personality variables. All signature moves, taunts and mannerisms - From Elbow to Eyebrow!' FROM games WHERE igdb_id = 6443 ON CONFLICT (game_id, language_code) DO NOTHING;
