INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Close Combat 5: Invasion: Normandy - Utah Beach to Cherbourg', 'On June 6th, 1944 the combined forces of the United States, Great Britain, Canada and France launched the greatest amphibious invasion in the history of the world. The blow fell in Normandy, France - striking Adolph Hitler''s Atlantic Wall with nine divisions of assault troops plus support from navel gunfire and massive air strikes. Close Combat lets you relive this monumental battle in real-time tactical detail.' FROM games WHERE igdb_id = 124960 ON CONFLICT (game_id, language_code) DO NOTHING;
