INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trump Collection 2: Bottom Up Teki Sekai Isshuu no Tabi', 'The previous Trump Collection title included four different games: Grand Millionaire, One-card, Blackjack and Poker. This time around, the four games included are: Speed, Nervous Breakdown, Seven in a Row and Dobon. The item collection system, which was popular in the previous title, is still in place. In addition to the "Normal Mode" for enjoying the game as usual, a "Round the World Mode" has been added in which players can travel to famous places around the world to collect items.' FROM games WHERE igdb_id = 82136 ON CONFLICT (game_id, language_code) DO NOTHING;
