INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dynamite Bomber', 'A challenging platform game from Limenko that has many different stages and bosses including a giant robot on the moon. Dynamite Bomber was produced by Limenko in 2000. Limenko released 5 different machines in our database under this trade name, starting in 2000. Other machines made by Limenko during the time period Dynamite Bomber was produced include Happy Hunter, Battle Bubble, Legend of Heroes, and Techno X.' FROM games WHERE igdb_id = 266879 ON CONFLICT (game_id, language_code) DO NOTHING;
