INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mystical Ninja Starring Goemon', 'Mystical Ninja Starring Goemon is a colorized port of Ganbare Goemon: Sarawareta Ebisumaru!, released as part of Konami GB Collection Vol. 3 for the Game Boy Color in Europe. This version marks the game''s first release in English, since the original Game Boy version was exclusive to Japan. Gameplay is similar to Ganbare Goemon! Karakuri Douchuu which was released on the Famicom. Only Goemon is playable, and the game consists of him rescuing Ebisumaru; Sasuke and Yae do not make appearances.' FROM games WHERE igdb_id = 280484 ON CONFLICT (game_id, language_code) DO NOTHING;
