INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Prodigy Racing', 'Prodigy Racing is a mouse-operated 3D racing game. It is the third game in Yoichi Hayashi''s Prodigy series. In this futuristic racer, players can choose from a selection of five tracks and two game modes. Pilots operate a machine equipped with an anti-gravity engine and race through a high-speed thrill of up to 400 km/h.' FROM games WHERE igdb_id = 311287 ON CONFLICT (game_id, language_code) DO NOTHING;
