INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crusader of Aurium', 'Aurium is a mini-adventure that was presented at the MiniComp2 contest organized by the CAAD, but at the last minute, after a small discussion, it was disqualified. And this was not done because of anything special about the game itself, but because the contest was about conversational adventures and this was a graphic, hence the discussions that arose.' FROM games WHERE igdb_id = 317058 ON CONFLICT (game_id, language_code) DO NOTHING;
