INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Maurice Sendak''s Little Bear: Toddler Discovery Adventures', 'Little Bear and his friends have gathered together in the meadow. Clicking on any one of the characters from the main screen will bring the player to a learning activity. Each character hosts a different learning activity, all of which Little Bear is present for to explain how each activity works. All of the activities are designed to encourage early learning skills for children ages 18 months to 3 years.' FROM games WHERE igdb_id = 316781 ON CONFLICT (game_id, language_code) DO NOTHING;
