INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sports Superbike', 'Open the throttle on awesome superbikes in this adrenaline packed racer. Enter races of up to 8 competitors over four varied and incredibly realistic tracks. Featuring fantastic graphics and sound, and super fast gameplay, Sports Superbike provides a heart-stopping race to the chequered flag.' FROM games WHERE igdb_id = 43789 ON CONFLICT (game_id, language_code) DO NOTHING;
