INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fushigi Deka', 'A Capcom developed adventure game released exclusively in Japan for the PlayStation. Cursor-selective adventure game. The player takes on the role of a detective transferred from the main police department to investigate a murder on a surrealistic island. The investigation is always accompanied by slapstick jokes. The story progresses by switching between "Investigate" and "Move" modes with the buttons, selecting the object to be investigated with the cursor, and using the items obtained on the object. The difficulty level is low, as at any time by pressing the button, your buddy, Detective Nekonya, will give you hints on how to proceed.' FROM games WHERE igdb_id = 59442 ON CONFLICT (game_id, language_code) DO NOTHING;
