INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pepsi-max-extreme-sports', 110806, '2000-10-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coapqi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc5hxj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pepsi Max Extreme Sports', 'Play it to the Max! with Pepsi Extreme Sports, the closest you can get to the real thing on your PC. Show your Dad how to get fat air off the half pipe or impress your sister with a radical Bungee Jump. Pepsi Extreme Sports brings you full on extreme action such as Snowboarding, Speed Hang Gliding, Mountain Biking, Bungee Jumping, Sky Surfing and ATV Quad biking in a competitive arena, your PC. Packed full of variety and game play that is thrilling and absorbing this is a must have for all the family. Push your reflexes to the edge, make it massive, there are NO LIMITS!  Features  Three main modes of play; championship, single track and time trial with practice and bonus tracks also available  6 extreme sports to race; Snowboarding, Speed Hang Gliding, Mountain Biking, Bungee Jumping, Sky Surfing and ATV Quad biking  Perform awesome tricks and gain extra kudos and speed benefits  Attack the other competitors to help you gain places in the races  12 multi-environment tracks in 5 exotic locations with various weather conditions and lighting conditions' FROM games WHERE igdb_id = 110806 ON CONFLICT (game_id, language_code) DO NOTHING;
