INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'AmsterDoom', 'Aliens have conquered Amsterdam and the player has to drive them back. The defining feature of this game is that all levels are closely modeled after real-life locations; e.g. the dam, the red light district or the wax museum. The rest of the game features straightforward level design with five basic weapons to choose from.' FROM games WHERE igdb_id = 94385 ON CONFLICT (game_id, language_code) DO NOTHING;
