INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vampiric Tower', 'Vampiric Tower is a quirky puzzle game that includes 50 puzzles of quickly increasing difficulty. While most of the puzzles involve familiar pushing/collecting exercises, there is also an additional element at play here. Your character can sometimes transform into a bat, which can help you by letting you past certain types of obstacles.' FROM games WHERE igdb_id = 69853 ON CONFLICT (game_id, language_code) DO NOTHING;
