INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Eyes: Millennium 2000', 'Dark Eyes: Millennium 2000 is set in a three-way planetary war between the monsters that invade the planet Fairhope, the Shadow Chief, and the two great powers of Infan and Ogal, who control the planet. Players belong to either the Infan or Ogal race, act according to their respective purposes, and build the history of the planet.  Very little is known about this title beyond it''s previous listing of NEXTECH''s website.' FROM games WHERE igdb_id = 145632 ON CONFLICT (game_id, language_code) DO NOTHING;
