INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Astraware Zap!', 'Zap! is a top-down arcade shoot-em-up in space featuring numerous enemies and bosses to contend with across multiple levels. Its first iteration, simply titled Zap!, was first published in 1999 for Palm OS 3.x devices, but later received a full-color remake called Zap! 2000. An enhanced version of this remake, Zap! 2016, was later released with improved graphics and sound in 2003.' FROM games WHERE igdb_id = 257482 ON CONFLICT (game_id, language_code) DO NOTHING;
