INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Microsoft Combat Flight Simulator 2: WWII Pacific Theater', 'The sequel to Microsoft''s first Combat Flight Simulator, the focus shifts to the Pacific theater, where carrier battles and island hopping dominate the strategy. Fly for the Japanese Navy or the American Navy/Airforce in either single battles or branching campaigns. Controllable aircraft include the standard Zero, the P-38, Wildcat, Hellcat, Corsair, and George, each fighter representing different design philosophies from the most nimble Japanese planes to the powerhouse American designs. Escort bombers, strafe transports, and provide CAP for your carrier group. Learn how to successfully land on a carrier in strong winds.' FROM games WHERE igdb_id = 644 ON CONFLICT (game_id, language_code) DO NOTHING;
