INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Li''l Pac-Man', 'Li''l Pac-Man is a handheld LCD game released by Playskool in 2000. It is a very basic game intended for toddlers and preschoolers, which plays like a simplified version of Kaboom! for Atari 2600. The handheld was only test marketed in select K-Mart stores, and is very hard to find today.' FROM games WHERE igdb_id = 219345 ON CONFLICT (game_id, language_code) DO NOTHING;
