INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Love Hina: Totsuzen no Engeji Happening', 'There is a new girl in the Hinata Sou. Her name is Fujisawa Mizuho and she is a Tokyo University Student. She is asked by Keitarou-kun''s grandmother to become a tutor for Keitarou-kun. If Keitarou-kun fail to pass the coming Entrance Exam for Tokyo University, Mizuho-chan says that she will take the responsibility for it and marry Keitarou-kun.' FROM games WHERE igdb_id = 46375 ON CONFLICT (game_id, language_code) DO NOTHING;
