INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sakura Taisen GB: Geki Hanagumi Nyuutai!', 'You have been ordered to a probational enrollment of 1 month after meeting Imperial Combat Revue''s Vice Captain Ayame Fujieda, who has been searching all over Japan to find people with great spiritual power. In this game you will meet 6 members of the Imperial Combat Revue and aim to complete your graduation exam. To commemorate the release of this software, a Game Boy Color system with a clear cherry-pink design featuring cherry blossoms on the screen cover was released as a limited edition with the game. The game received a machine translation in 2021.' FROM games WHERE igdb_id = 79482 ON CONFLICT (game_id, language_code) DO NOTHING;
