INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'All-Star Baseball 2001', 'The last All-Star Baseball release on the N64 once again includes some new features as well as improvements in relation to previous play modes & options. For 2001, a new team is included, The Coopertown Legends, featuring a selection of some of the finest players to ever grace the MLB, including Yogi Berra, Willie Stargell and Reggie Jackson. Along with the legends team, you can choose from every player, team and stadium from the real 2000 MLB season. Each player includes facial expressions and looks inspired to realism, plus motion-captured player movements, batting stances and reactions to key events during play.' FROM games WHERE igdb_id = 69229 ON CONFLICT (game_id, language_code) DO NOTHING;
