INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('truck-kyousoukyoku', 77490, '2000-06-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co98nb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar392g.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Truck Kyousoukyoku', 'A Japan-exclusive arcade game featuring comedic truck driving. The Dekotora or Decotora, an abbreviation for "decoration truck", is a type of extravagantly decorated truck in Japan. Commonly displaying neon or ultraviolet lights, extravagant paints and stainless or golden exterior parts, on both on the exterior and the interior. Dekotora may be created by workers out of their work trucks for fun, or they may be designed by hobbyists for special events. They are sometimes also referred to as Art Trucks. Truck Kyousoukyoku - Ai to Kanashimi no Rodeo: Taking inspiration from the hugely popular decotora truck games. As a truck maneuvering maniac, your goal is to race against competing truckers any which way but loose. Drive on sidewalks, search for shortcuts, discover secret roads and plunge headlong into traffic with no reservation. You are, after all, a maniac. Upon winning races, the player gets a can of aerosol to paint designs and emblems on the body of the truck. The sides, top, back, and head of the vehicle are open canvases for you to drop paint and swirl a menacing symbol or a nature panorama. Preset designs may be chosen or you can create your own doodles which help you help your truck emote. The action is hot and the paint jobs add to the ambience.' FROM games WHERE igdb_id = 77490 ON CONFLICT (game_id, language_code) DO NOTHING;
