INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cannon Spike', 'Cannon Spike (released in Japan as Gunspike) is a top-down run-and-gun shooting game developed by Psikyo & published by Capcom in the year 2000. Players select from a roster of classic Capcom characters, then play through a series of short stages & boss battles in a randomly selected order.' FROM games WHERE igdb_id = 6719 ON CONFLICT (game_id, language_code) DO NOTHING;
