INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('battle-of-the-youstrass', 229213, '2000-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9jhy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sckcai.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle of the Youstrass', 'Battle of the Youstrass is a shareware Japanese-style tactical role-playing game. The game takes place on the world of Youstrass where two countries share a single continent and where technology and magic co-exist. One of the countries, Kradion, is largely frozen. Its people are famous for their mercenary soldiers and mechanical fighters. The other country, Welfrad, is prosperous and fertile. Kradion depends on imported food. When the great famine struck there was no food available and times were hard, so Kradion attacked Welfrad, all but destroying Welfrad''s royal knight units. Just a few ace units survived because they were not in the capital when the attack came. Among these is Ryuke, aka Blue Wing, chief knight of the royal army, who pilots the elemental fighter Huben Drake. The game starts with Ryuke separated from surviving units. He must survive and join his comrades to wage guerrilla war on the enemy. The game consists of large-scale tactical battles, which are played on an isometrically viewed map, only part of which can be seen at once. There is a mini map in the lower left of the screen which shows the whole game area and the location of any other units, both friends and foe. During actual battles between units the game switches to a different view which displays the combat. As combat progresses the character collects experience points, special items, and additional special abilities.' FROM games WHERE igdb_id = 229213 ON CONFLICT (game_id, language_code) DO NOTHING;
