INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Land Before Time: Dinosaur Arcade', 'The Land Before Time: Dinosaur Arcade is an educational game for Windows-based PCs intended for children ages 4-7 released by Sound Source Interactive in North America in November 2000. The game features five minigames revolving around Littlefoot, Spike, Petrie, Ducky, and Chomper that involve guiding them around various levels and a pinball-style game. Children''s Software Review noted that it was less educational than others in its genre, calling it a "strictly an entertainment title", with little real educational value except for some practice with eye-hand coordination and logic.' FROM games WHERE igdb_id = 206996 ON CONFLICT (game_id, language_code) DO NOTHING;
