INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chromium B.S.U.', 'Chromium B.S.U. is an arcade-style, top-scrolling space shooter available on Windows, iPhone, PSP, Mac, AmigaOS 4, Linux and numerous other UNIX-like operating systems. It is a free software distributed under the Clarified Artistic License.' FROM games WHERE igdb_id = 121935 ON CONFLICT (game_id, language_code) DO NOTHING;
