INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('omega-chase-deluxe', 273282, '2000-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co79sk.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Omega Chase Deluxe', 'Omega Chase (non-deluxe version) is the predecessor to Omega Chase Deluxe and was a download only version of the game. While there are a number of differences between Omega Chase and Omega Chase Deluxe, Omega Chase is included on Omega Chase Deluxe along with the game Zap. The main difference between the two versions of the game is that with Omega Chase, the enemies travel in only one direction around the center of the track, but in Omega Chase Deluxe, the enemies travel from both sides simultaneously. Creator Christopher Tumber felt there was no need to release the original file on cartridge as it was included on the compilation of the game.' FROM games WHERE igdb_id = 273282 ON CONFLICT (game_id, language_code) DO NOTHING;
