INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TechnoMage: Return of Eternity', 'Enter into an action-packed and thrilling adventure! Gothos, a world full of secrets and strange creatures and of two cultures; one technically gifted and inventive, the other blessed with knowledge and magical powers. Yet both face a common threat. You assume the role of Meliv, the TechnoMage. In your eventful travels through fascination worlds, you will meet curious peoples, bizarre characters and the enchanting Talis, who shares your destiny. It was only ever released in the PAL region.' FROM games WHERE igdb_id = 44906 ON CONFLICT (game_id, language_code) DO NOTHING;
