INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BlockBuster', 'The mobile game Block Buster is a Breakout variant. The player controls a paddle at the bottom of the screen used to to hit a ball, which in turn hits the blocks. Sometimes when the ball hits a block, an item drops from it, providing multiple balls, a change of speed or altering the paddle size. To move on to a next stage, all blocks need to be removed from the screen. The game has 8 stages.' FROM games WHERE igdb_id = 327741 ON CONFLICT (game_id, language_code) DO NOTHING;
