INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TVDJ', 'TVDJ is an action/rhythm game that was only released in Japan by SCEI. An impressive early PS2 game, it has cel-shaded graphics and is fully voice acted. Unfortunately, the game is only a a handful of short 5-minute stages that end up feeling more like a mini-game.' FROM games WHERE igdb_id = 78391 ON CONFLICT (game_id, language_code) DO NOTHING;
