INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SnoCross Championship Racing', 'Sno-Cross Championship Racing provides players with the opportunity to race 12 snowmobiles by Yamaha. In the championship mode snowmobiles can be upgraded with money won by winning races and performing tricks. There are 10 racing circuits set in such locations as Nagano, Aspen, and Munich. A track editor is included as well so that users can modify current tracks or create their own. Strap on your goggles and helmet, choose your favorite Yamaha sled, and hit the courses. Gain experience day and night, sun rain or snow, racing on the icy flats of Vladivostok, the slopes of Aspen, and the tunnels of Nagano.' FROM games WHERE igdb_id = 45035 ON CONFLICT (game_id, language_code) DO NOTHING;
