INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'EZ2Dancer', 'EZ2Dancer is a series of dance video games developed by the Korean video game company Amuseworld. The gameplay of the series is similar to other dance simulation games, but unlike most games of their genre, EZ2Dancer incorporates both hand sensors and foot sensors into gameplay.' FROM games WHERE igdb_id = 92487 ON CONFLICT (game_id, language_code) DO NOTHING;
