INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Steel Panthers: World at War!', 'The first project of Matrix Games, basically a remake of Steel Panthers using the Steel Panthers III engine. Includes MegaCampaigns, featuring branching linked scenarios. This is the General Edition of the historical wargame Steel Panthers World At War and includes all four Mega-Campaign games and a free v8.20 of SP:WaW.' FROM games WHERE igdb_id = 14468 ON CONFLICT (game_id, language_code) DO NOTHING;
