INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Street Fighter II X for Matching Service', 'Super Street Fighter II X for Matching Service is a fighting game developed by Capcom and released for the Sega Dreamcast exclusively in Japan in 2000. It is an enhanced port of Super Street Fighter II X: Grand Master Challenge (known as Super Street Fighter II Turbo in Western regions), which was the final arcade update to Street Fighter II. The game plays similarly to other ports of Super Street Fighter II X (including the earlier Sega Saturn version that was released as part of Street Fighter Collection), but it was compatible with Capcom''s Matching Service, meaning players could compete online.' FROM games WHERE igdb_id = 307486 ON CONFLICT (game_id, language_code) DO NOTHING;
