INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Destruction Derby Raw', 'Destruction Derby Raw is a vehicular combat game for PlayStation where players drive cars in demolition derbies and races. The main objective is to damage other vehicles or be the last one standing while avoiding getting destroyed. Players can choose from different cars, each with unique stats, and can upgrade them as they progress. The game features various modes, including free-for-all battles and racing on closed tracks, with a focus on destruction and survival.' FROM games WHERE igdb_id = 1169 ON CONFLICT (game_id, language_code) DO NOTHING;
