INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nfl-gameday-2001', 43763, '2000-09-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/mwiqcitxrhkclwi6mpwt.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NFL GameDay 2001', 'This edition features lifelike player specific graphics that make players look like their real life counterparts. Also new is commentary by Dick Enberg and Phil Simms. Another feature is total-control passing and running. Total-control passing lets you lead, overthrow, and underthrow your receivers so that you can throw more completions and prevent defenders from intercepting your passes. The play editor has been improved making it easier to make new patterns for your receivers and running backs. The general manager mode has also been changed, mostly to help you with the draft so you can easily see what areas of your team need improvement.' FROM games WHERE igdb_id = 43763 ON CONFLICT (game_id, language_code) DO NOTHING;
