INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vasara', 'Vasara is an arcade scroll shooter game released by Visco in 2000. All six stages. The motif is the Battle of Sekigahara and the Jin of Osaka, but all the cavalry has been replaced with air bikes, and battleships and tanks have appeared, creating a worldview that could be described as the sci-fi Warring States period.' FROM games WHERE igdb_id = 40293 ON CONFLICT (game_id, language_code) DO NOTHING;
