INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MoHo', 'MoHo is a Sega Dreamcast game developed by Lost Toys and published by Take 2 Interactive in 2000. It is notable for being the only exclusive Dreamcast game for the United Kingdom, despite receiving ratings from the German USK and French SELL ratings bodies and having its back cover description translated into German. An American release under the name of Ball Breakers was planned for release in November 2000[5], but cancelled near completion; three different rips of a late prototype were leaked simultaneously in 2012.' FROM games WHERE igdb_id = 176877 ON CONFLICT (game_id, language_code) DO NOTHING;
