INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A2 Racer III: Europa Tour', 'Part 3 in the Dutch A2 Racer series takes the player to London, Berlin and Vienna. The gameplay remains the same with illegal street races on well known highways and cities. During the races players have to collect power-ups, like money, fuel and time extensions. He has to avoid getting caught by the cops and reach the finish line before his opponents do.' FROM games WHERE igdb_id = 44841 ON CONFLICT (game_id, language_code) DO NOTHING;
