INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Armada F/X Racers', 'Put adventure into overdrive, as you captain a futuristic vehicle, and race through six alien worlds to face off in a battle of wills, thrills, chills and spills. Take on opposing high-tech vehicles, obstacles and obstructions - all as you approach a final showdown against multiple-bosses in a good ''ol game of bumper cars, minus the bumpers.' FROM games WHERE igdb_id = 65681 ON CONFLICT (game_id, language_code) DO NOTHING;
