INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metamorphoses', 'You wake to stillness. The hammering, banging, and shouting that kept you awake half the night are gone. The air is cold, and something smells burnt. Your master''s experiments must be finished, but with what result? A piece of Interactive Fiction written by Emily Short.' FROM games WHERE igdb_id = 60115 ON CONFLICT (game_id, language_code) DO NOTHING;
