INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Jornada', 'The player commands Sirey, the blue-haired kid. His first mission is very naïve, to clean the house’s backyard. Of course, things will soon get more complicated until Sirey fights for humankind''s destiny against the alien invasion. For that, he’ll have to recover a robot project long forgotten, the Teenook.' FROM games WHERE igdb_id = 299469 ON CONFLICT (game_id, language_code) DO NOTHING;
