INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('arcturus-the-curse-and-loss-of-divinity', 13958, '2000-12-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co28mi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scjfr7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arcturus: The Curse and Loss of Divinity', 'Korean RPG developed by Gravity (makers of Ragnarok Online) and Sonnori and later published in Japan by Nihon Falcom. Predecessor to Ragnarok Online with interesting characters and world and combat system similar to Grandia. Arcturus is a Korean-made role-playing game in Japanese style, similar to Grandia II in visual presentation. The player can choose between two prologues chapters (either Elluard''s or Sizz''s), after which the two stories converge. There is no overworld in the game, and areas are interconnected. Battles take place in the same environment as exploration, and are turn-based. The player can navigate characters on the battle field and also take their speed rankings into account, as executions of attacks and other moves depends on them. Magic can be learned by certain characters and is divided into four elements: Water, Air, Earth, and Fire. Casting spells requires a certain amount of real time when in combat. Characters learn new spells by repeatedly using available ones in the correspondent category. Those who do not have access to magic can execute various special attacks with their own separate point gauges. In addition to HP, characters also have "barrier points", which are reduced first when enemies damage them.' FROM games WHERE igdb_id = 13958 ON CONFLICT (game_id, language_code) DO NOTHING;
