INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fast Food Tycoon', 'Fast Food Tycoon was developed by Software 2000 as a economic simulation game. The player controls a pizza chain syndicate, and is able to manage many of the different aspects of running a pizza chain. The game spawned a sequel, and is generally regarded as an average-quality eco-sim.' FROM games WHERE igdb_id = 8912 ON CONFLICT (game_id, language_code) DO NOTHING;
