INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sega GT', 'With a nod towards GT2, Sega tosses in their entry in the race-career-category, meaning that this game is all about racing. Racing to win competitions, cars, money and other prizes (such as licenses for bigger cars), buying new cars to race in, upgrading cars to race in and gaining licenses to race with. It features realistic controls, graphic and physics, and spans over career, multiplayer or arcade modes, and hundreds of cars to boot.' FROM games WHERE igdb_id = 28838 ON CONFLICT (game_id, language_code) DO NOTHING;
