INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Supercross Freestyle', 'Supercross Freestyle is a dirt bike racing game. The game features three game modes: Freestyle, Supercross and Arcade. Freestyle is all about making impressive jumps and tricks with your bike. Supercross and Arcade are racing modes, where Arcade has different courses and power-ups that can change the odds. The game features 24 different tracks and 16 different tricks.' FROM games WHERE igdb_id = 50069 ON CONFLICT (game_id, language_code) DO NOTHING;
