INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'F1 Manager', 'F1 Manager is a sports video game developed by Intelligent Games and published by EA Sports exclusively for Microsoft Windows. It was the last officially licensed F1 Management game until F1 Manager 2022 by Frontier Developments. The game takes place from the 1999 Formula One World Championship onwards. The player assumes the role of the team principal of a Formula One constructor, managing and negotiating various aspects of the team.' FROM games WHERE igdb_id = 46448 ON CONFLICT (game_id, language_code) DO NOTHING;
