INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Maya the Bee: Garden Adventures', 'This game uses the license from the famous German TV series Biene Maja. Maja''s best friend Willi is kidnapped by the hornets, the enemies of the bees. In this game you are playing Maja the bee and has to free Willi. In this adventure you have to solve some puzzles, finding things to get further. Inside the hornets nest you have to hide and seek to not get caught.' FROM games WHERE igdb_id = 198181 ON CONFLICT (game_id, language_code) DO NOTHING;
