INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'This is Football 2', 'The sequel to ''This Is Football'', attempts to make a realistic yet enjoyable football game. Fully licenced by FIFAPro (International Association of Football Players'' Unions) to use every players real name, dozens of the most famous football stadiums from around the world (Mexico, England, Italy, etc.) are faithfully represented while nearly every major football league, cup or competition is included.' FROM games WHERE igdb_id = 44833 ON CONFLICT (game_id, language_code) DO NOTHING;
