INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Activity Center: Winnie the Pooh', 'Winnie the Pooh and the Blustery Day: Activity Center is a PC game from 2000. Winnie the Pooh''s Activity Center is a wonderful way to entertain your child on a rainy day; with six different activities at three different difficulty levels, kids of all ages can enjoy time spent inside. Also included is the animated storybook Animated StoryBook: Winnie the Pooh and Tigger Too, which offers more fun games and reading activities. In the Winnie the Pooh''s Activity Center, a friendly narrator greets you on "a blustery day." He presents activities such as Eeyore''s house hunt--help Owl to find a new home; Heffalumps and Woozles--match the characters in Pooh''s dreams; and Fly a Piglet--prevent Pooh and Piglet from running into trees and stumps. You may also choose to read the interactive book of Winnie the Pooh and the Blustery Day, which introduces different activities as you read the story along with the characters.' FROM games WHERE igdb_id = 209035 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 209035 AND p.igdb_id = 6 ON CONFLICT DO NOTHING;
