INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'GunDress', 'In 2100, the newly built Bayside City serves as Japan''s premier international port. The Angel Arms Company is established by a former policewoman named Takako, to help wage war on terrorism with armed security suits. When the mayor is assassinated, the women of Angel Arms end up protecting the evil crime-lord Hassan, in hopes that his information will help bring down a global terror ring. Takako''s back is to the wall as a band of criminals plot to kill Hassan, and the organization''s leader is revealed to be the former lover of Angel Arms'' own Alisa.' FROM games WHERE igdb_id = 213042 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 213042 AND p.igdb_id = 7 ON CONFLICT DO NOTHING;
