INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dirt Track Racing: Australia', 'Dirt Track Racing hits Australia! (Designer''s home turf) Starring 6 additional Australian muscle cars (the Holdens). Twelve different series, 3 different classes of cars (total of 24), 30 different tracks of ovals, tri-ovals, D-ovals, and figure-8''s, full career mode including parts, tuning, sponsors. Force feedback support based on actual car physics, changing track conditions, and more! Race up to 9 other players online!' FROM games WHERE igdb_id = 73507 ON CONFLICT (game_id, language_code) DO NOTHING;
