INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Xtreme Sports', 'Sega Extreme Sports, known simply as Xtreme Sports for the North American release and as Pepsi Max Extreme Sports for the Windows version, is a sports game developed by Norwegian video game development company Innerloop Studios and published by French holding company Infogrames for the Dreamcast and Microsoft Windows, and Sega for the European Dreamcast version. The Dreamcast version features a soundtrack licensed from the electronic music label Ninja Tunes and includes tracks from artists such as Amon Tobin, Coldcut, and DJ Food.' FROM games WHERE igdb_id = 127512 ON CONFLICT (game_id, language_code) DO NOTHING;
