INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nightmare Creatures II', '"Assume the role of Herbert Wallace, an escaped test subject, on the trail of the demonic scientist, Dr. Adam Crowley. After enduring years of horrific lab experiments, Wallace is out to settle the score in a chilling and bloody chase through London and Paris. Little does he know that exacting revenge on Crowley is also the last hope to save the world from a nightmarish demise."' FROM games WHERE igdb_id = 45860 ON CONFLICT (game_id, language_code) DO NOTHING;
