INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Angel', 'I wake peacefully, and already she is there. My angel - she is all around me. Her presence is like ice on water. But she is less than peaceful. My thoughts are all of raging storm clouds. Hurriedly, I drag myself up. A work of interactive fiction by Jon Ingold.' FROM games WHERE igdb_id = 217770 ON CONFLICT (game_id, language_code) DO NOTHING;
