INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Street Sk8er 2', 'This is a skateboarding game very similar in gameplay to Tony Hawk''s Pro Skater. You pick a skater and go through different skate parks, selecting either pro or amateur settings. You can also create your own skate park. Multiplayer competition is also provded, including 4 player serial play. Street Sk8er 2''s sound track contains music from many well known bands such as Deftones, Ministry, and Static X.' FROM games WHERE igdb_id = 45033 ON CONFLICT (game_id, language_code) DO NOTHING;
