INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Love Hina 2: Kotoba wa Konayuki no You ni', 'The Winter has begun in Hinata. X-mas is coming up. There are rumors about this special christmas eve: If someone is going to confess his love on this christmas eve, any wish will come true. Keitaro decides to confess his love to Naru. But he isn''t the only one confessing on this christmas eve... Link up with your PocketStation and gather all the words to win the heart of your love!' FROM games WHERE igdb_id = 43837 ON CONFLICT (game_id, language_code) DO NOTHING;
