INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beatmania GB Gotcha Mix 2', 'Beatmania GB Gotcha Mix 2 is a videogame launched for Game Boy Color. It has 25 songs and it''s the last portable videogame for beatmania franchise, and it''s the only one from the trilogy to have "Duet" charts, which two players are needed to play this level via Game Boy link cable, two GBC''s, and two copies of the same game.' FROM games WHERE igdb_id = 65667 ON CONFLICT (game_id, language_code) DO NOTHING;
