INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('beatmania-iii-the-latest-evolution-machine', 61017, '2000-03-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2cgh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8eka.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'beatmania III -The latest evolution machine-', 'beatmania III is a rhythm game developed by Konami. It is the first game in the beatmania III series, a spin-off of the beatmania series. It is part of the BEMANI franchise. The game is played with a controller with one turn table, one foot pedal and 5 keys, three white and two black. On the screen you will see bars moving from the top to bottom in columns representing each of the keys, foot pedal and the turntable. When the bars reach the judgement line it is time to scratch. This game starts the beatmania III spinoff series, which introduces the foot pedal into the game, which has separate notes tied to it. The foot pedal can also be configured to act as one of the 5 regular keys as well. Since the series features upgraded hardware in comparison to the main series, the game has more fluid movies and animation and the interface is generally more colorful. The effector table is also expanded. The cabinet has a floppy disk slot on which you can save scores, unlocked songs and game modes. A headphone jack is also included. This is the only game in the series with brand new songs, the rest of the games were released as "APPEND" games, pulling in songs from their beatmania counterpart. The game has 87 songs pulled from beatmania - beatmania 5thMIX and 23 brand new songs, for a total of 110 songs.' FROM games WHERE igdb_id = 61017 ON CONFLICT (game_id, language_code) DO NOTHING;
