INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pop''n Music Animelo', 'Pop''n Music Animelo (Pop''n Music アニメロ) is a rhythm video game developed by Konami and released on Arcade platforms in March 2000 in Japan. The game was later released on PlayStation under the name Pop''n Music: Animation Melody in July 2000 in Japan. It is a spinoff entry in the Pop''n Music series.' FROM games WHERE igdb_id = 72840 ON CONFLICT (game_id, language_code) DO NOTHING;
