INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Minigame 3-hon Pack', 'Minigame 3-hon Pack collection of SoulCalibur-themed minigames released for VMU as an online download after the release of SoulCalibur, only in Japan. After beating the minigames, the players were awarded with an alternate costume for Voldo. The included minigames are: - Word Scramble - Voldo Panic - Cannon Dare' FROM games WHERE igdb_id = 227750 ON CONFLICT (game_id, language_code) DO NOTHING;
