INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Love Story', 'ØSTORY (Love Story) is a full-motion video adventure about a dead man after a motorcycle accident. Then appears the Japanese Angel of Love, who gives them a second chance, so long as Rina falls in love with them in 6 days. Developed by General Entertainment and published by Enix in 2000.' FROM games WHERE igdb_id = 90934 ON CONFLICT (game_id, language_code) DO NOTHING;
