INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heisa Byouin', 'The game puts the player inside a hospital where the main character has to solve a series of murder cases. As soon as he arrives things starting to go even worse and more people are killed, can you help him solve this horror mystery? The game features good cg graphics for the characters and the building, japanese voice acting and different endings depending of the actions of the player.' FROM games WHERE igdb_id = 112555 ON CONFLICT (game_id, language_code) DO NOTHING;
