INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Breakout', 'An updated remake of the 1976 Arcade classic of the same name, Breakout for the PlayStation dispenses with the simplistic lines and dots of the original game and adds power-ups, 3D interactive worlds, multiple levels (that must be unlocked) and, of course, a storyline. Only the basic objective remains the same: maneuvering a paddle to keep a ball in play so it can ricochet off a wall of bricks (or other items in this case), effectively eliminating the bricks from the playfield.' FROM games WHERE igdb_id = 140838 ON CONFLICT (game_id, language_code) DO NOTHING;
