INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moses Prince of Egypt', 'Found by the river, and adopted into the royal family of Egypt, Moses must start on a quest to save his true people, the Israelites, from misery at the hands of their cruel Pharaoh. As well as a great half-hour cartoon video, Moses: Prince of Egypt features an easy-to-use virtual colouring book and a challenging puzzle game. Can the prince of Egypt fulfil his destiny?' FROM games WHERE igdb_id = 43783 ON CONFLICT (game_id, language_code) DO NOTHING;
