INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '3D Recon', 'The federation is engaged in a brutal war with the bloodthirsty, vicious aliens. The aliens are preparing to unleash the most destructive weapon known to man. RECON has been enlisted to find and eliminate the potential threat. As one of the elite RECON pilots you will have access to state of the art weaponry. Filled with explosive action and heart-pounding visual effects, your journey will ultimately decide the fate of the universe...' FROM games WHERE igdb_id = 57651 ON CONFLICT (game_id, language_code) DO NOTHING;
