INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Buffy the Vampire Slayer', 'Fight against the vampires to save mankind, or at least around Sunnydale. Punch and kick your way through 8 side-scrolling levels as Buffy the Vampire Slayer, beating back the vamps and staking them when the time is right. Comic book style cutscenes help to explain the story as you play, as if an episode of the TV show was on the handheld.' FROM games WHERE igdb_id = 206690 ON CONFLICT (game_id, language_code) DO NOTHING;
