INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-wild-thornberrys-rambler', 49983, '2000-12-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa0n3.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Wild Thornberrys: Rambler', 'The Wild Thornberrys are trying to win the Golden Schweitzer, an award given for the best nature documentary in the world. You take control of Nigel, Marianne, Eliza, Darwin, Debbie, and Donnie as they travel through six wacky levels of action. Along the way, they will have to travel to exotic locations like the Galapagos Islands, Amazon Rain Forest, Savannah Desert, African Congo, Himalayan Mountains, and Australian Outback. Each area has unique mini-games that can be set to three different difficulty levels. The games include sneaking up on animals and videotaping them, driving the Thornberry bus through the jungle, and helping Nigel collect items as he rappels down the side of a cliff. When you complete a game, the difficulty level determines what ending you see. Help the crew win the big award in THE WILD THRONBERRYS: Rambler.' FROM games WHERE igdb_id = 49983 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 49983 AND p.igdb_id = 22 ON CONFLICT DO NOTHING;
