INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nanatsu no Hikan: Senritsu no Bishou', 'The player can control one of two characters: Kei and Reina. The game can be played in either first person, third person, or fixed camera angle views. Kei''s levels are more action based, while Reina''s are more adventure-based. There is also a unique multiplayer cooperative mode where one player controls Kei and the other Reina. This mode is different from the single-player mode, as it is much shorter and objectives, monsters, and events are all altered.' FROM games WHERE igdb_id = 108772 ON CONFLICT (game_id, language_code) DO NOTHING;
