INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Donkey Kong GB: Dinky Kong & Dixie Kong', 'Fame-and-fortune seekers have flooded Donkey Kong Country in search of the fabled Lost World. You command Dixie Kong and Kiddy Kong through 36 Kong-sized levels of action and adventure. Use your animal friends - Squitter the spider, Squawks the parrot, Ellie the elephant, Enguarde the swordfish and Parry the parallel bird - to help you prove your adventuring skills and find the Lost World before someone else does! In this updated version of Donkey Kong Land III, enjoy the classic adventure now in full color exclusively released in Japan.' FROM games WHERE igdb_id = 50039 ON CONFLICT (game_id, language_code) DO NOTHING;
