INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('casper-friends-around-the-world', 44956, '2000-12-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4sn4.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Casper: Friends Around the World', 'Casper''s friends have been hexed by an evil spell! The king of ghosts has created an imprisoning device that sends them to different locations across the globe. You must help Casper rescue his friends, but you only have the first ten map pages. If you can find the rest, they will each lead you to a friend. Collect the pieces of the device that sent your friends away by defeating three evil bosses. If you can manage to find everything in the game, then you''ll advance to a special level in the lost city of Atlantis. Watch out for your uncles and tourists, though, because they will make your journey most difficult. Make Casper jump on umbrellas and trees to reach high places, while using his special ability to levitate to avoid pitfalls and water. You can also make him turn into a parachute to glide down to the surface and duck to avoid flying objects. Ghostly Spheres can be thrown to eliminate apparitions and pumpkin bombs.' FROM games WHERE igdb_id = 44956 ON CONFLICT (game_id, language_code) DO NOTHING;
