INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ring: Infinity', 'Ring: Infinity is a visual novel game. The game begins much like the other stories in the "Ring" series do by introducing you to the "Cursed Videotape". From there, you must find a way to save yourself, or perish.' FROM games WHERE igdb_id = 37495 ON CONFLICT (game_id, language_code) DO NOTHING;
