INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-land-before-time-return-to-the-great-valley', 45070, '2000-09-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9bz4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scv6zo.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Land Before Time: Return to the Great Valley', 'After being chased by a Sharptooth while returning a stolen egg, Littlefoot, Cera, Ducky, and Spike become lost in the Great Beyond. Players control the four prehistoric pals as they each must find the way back home in The Land Before Time: Return to the Great Valley for PlayStation. Journeying through five 3D levels, the characters must collect treestars while avoiding perilous pitfalls. Levels contain interactive elements, such as plants and tar bubbles. Depending upon the selected character, players can make use of tail whipping, head butting, and other abilities to build bridges, ride geysers, and overcome other obstacles. Petrie is also readily available to fly onscreen and offer advice and direction. Levels are composed of obstacle courses and puzzle-type action as players need to cross rivers, feed plants, and collect treestars while avoiding hazards, such as lava, water, and steep cliffs. After all five characters exit the fifth level, they are all reunited in the Great Valley.' FROM games WHERE igdb_id = 45070 ON CONFLICT (game_id, language_code) DO NOTHING;
