INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('doraemon-memories-nobita-no-omoide-daibouken', 91776, '2000-03-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9rri.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/schw8v.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doraemon Memories: Nobita no Omoide Daibouken', 'The game was produced and released in conjunction with the 30 year anniversary event of Doraemon''s manga. The purpose is to collect "memorial shots," which are excerpts of comics in action scenes inserted between scenes while watching dialogue between characters. The package illustrations are the anime pictures of the time, but the in-game graphics and settings such as calling Shizuka Minamoto "Shizu-chan" are in compliance with the manga, and there are dialogue scenes and quizzes that can not be understood without perusing the manga, making this a unique game that is clearly different in its target audience than before.' FROM games WHERE igdb_id = 91776 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 91776 AND c.slug = 'epoch' ON CONFLICT DO NOTHING;
