INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ronaldo V-Football', 'Ronaldo V-Football is the pinnacle of soccer experiences for the PSX. Endorsed by international legend, Ronaldo Luis Nazario de Lima, Ronaldo V-Football brings Brazilian soccer traditions to the rest of the world. Boasting more than 100 real teams from around the globe, the game is set to an awesome Samba soundtrack and graced by colorful graphics.' FROM games WHERE igdb_id = 44836 ON CONFLICT (game_id, language_code) DO NOTHING;
