INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bad Milk', 'Bad Milk is a puzzle video game developed by New York developers Dreaming Media. The game begins with a first person full motion video, in which the player drinks spoiled milk and collapses onto the table. This launches a puzzle game in which the player must complete a series of minigames to obtain clues to "escape" their situation. The player is spoken to in various phone calls by an unseen third party and given hints to complete the puzzles. Clues are hidden in FMV clips including a "dismembered bald head, a disembodied voice, a drowning man, and chronic smokers", and often use reversed audio.' FROM games WHERE igdb_id = 69755 ON CONFLICT (game_id, language_code) DO NOTHING;
