INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Championship Bass', 'Bass fishing reaches new level with Championship Bass! Artificial Intelligence creates the most realistic behavior in simulated bass ever. False strikes, swerves, return attacks, and short-strike lunges will keep you on the edge. Even if you do land a strike, watch these fish go for obstacles in order ot break your line! Multiple difficulty levels, plenty of tricks in your lure box, multiple game modes, multiple lakes, and more. Sit in a boat and go for the fish, or simulate a whole fishing trip. The choice is yours!' FROM games WHERE igdb_id = 45229 ON CONFLICT (game_id, language_code) DO NOTHING;
