INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Baroque Shooting', 'Baroque Shooting is a vertical scrolling shoot-’em-up. It serves as a spin-off from the dark, post-apocalyptic roguelike Baroque, reimagined as an arcade-style shooter. In the game, you control an angelic character flying through desolate ruins populated by grotesque enemies from the Baroque universe.' FROM games WHERE igdb_id = 73368 ON CONFLICT (game_id, language_code) DO NOTHING;
