INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tread Marks', 'Tread Marks is a tank action game featuring tree different gameplay modes. The first is race mode, in which players race each other on an off-road circuit and can push or shoot their opponents to hinder them. Battle mode is like deathmatch or team deathmatch, the most kills win the game. In capture the flag mode, two or more teams try to capture the other team''s flags.' FROM games WHERE igdb_id = 54181 ON CONFLICT (game_id, language_code) DO NOTHING;
