INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dangan', 'Dangan is a action multiscroll game that is set in a near future and puts the player in control of 2 counter-terrorist agents (Jack & Kate) that will have to defeat different enemies during 8 different operations. The game features a top down view and different weapons to choose and use.' FROM games WHERE igdb_id = 246216 ON CONFLICT (game_id, language_code) DO NOTHING;
