INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bubble Bobble Nostalgie: Christmas Edition', 'The developers of Bubble Bobble Nostalgia also released an add-on called Christmas Edition. In fact, this is the same Bubble Bobble Nostalgia, only with the atmosphere of the New Year or Christmas holidays: the title music is the notorious Jingle Bells, the dragons are dressed up in the costume of Santa Claus or Santa Claus, and the passwords are replaced with the names of attributes of the New Year or the same Christmas. Well, they changed the background and platforms in some levels. And the rest is the same.' FROM games WHERE igdb_id = 251124 ON CONFLICT (game_id, language_code) DO NOTHING;
