INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kanji de Puzzle', 'You can enjoy the world of puzzle game magazines published in various ways on GB. Most of the kanji to be asked are 1006 kanji learned in the 1st to 6th grades of elementary school. Acquire perfect while playing antonyms, synonyms, stroke order, okurigana, homophones and idioms. There are four types of games: Kanji quiz "Spartan Z", Kanji crossword "Kankuro", "Kanji puzzle", and original puzzle "Elephant Dragon". It can also be used as a kanji learning tool for children from general education.' FROM games WHERE igdb_id = 281601 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 281601 AND p.igdb_id = 22 ON CONFLICT DO NOTHING;
