INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Summon Night', 'Summon Night is a Japanese tactical RPG and the first entry in the Summon Night series. This game follows the story of a Japanese high schooler, who is suddenly summoned into the world of Lyndbaum. The main character gets involved in a series of conflicts between gangs, classes, factions and worlds. He/she has to use the power of summons to solve those problems while trying to return to his or her own homeworld.' FROM games WHERE igdb_id = 13063 ON CONFLICT (game_id, language_code) DO NOTHING;
