INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gran Turismo 2000', 'Gran Turismo 2000 is the original title of the project that became Gran Turismo 3: A-Spec, with the name being used for several demonstration builds and one demo disc. It was based on Gran Turismo 2, where the physics and graphics were updated to showcase what Polyphony Digital could do with the new hardware in the PlayStation 2.' FROM games WHERE igdb_id = 298017 ON CONFLICT (game_id, language_code) DO NOTHING;
