INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metamode', '"Metamode" is an action role-playing game for the Game Boy Color released by Koei in 2000. The goal is to maintain world peace by having the protagonist join the "Keibi-tai" and use a tool called "Metamode" to transform into various jobs.' FROM games WHERE igdb_id = 266358 ON CONFLICT (game_id, language_code) DO NOTHING;
