INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chaos', 'ChaoS is a Sonic fangame developed by Davie Slam, it focuses on a unique story surrounding the villain ChaoS causing Angel Island (Referred to as "Floating Island" ingame) to fall and split open. It is a platformer borrowing sprites from games such as Sonic 3, and Sonic 2 with many sprites borrowed from the prototypes of these games.' FROM games WHERE igdb_id = 300015 ON CONFLICT (game_id, language_code) DO NOTHING;
