INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mort the Chicken', 'The Chickens are in a panic when mysterious creatures from another world kidnap their baby chicks! Stolen from the farm and threatened with becoming tasty snacks, it is up to fearless Mort to come to their rescue. A super chicken with super powers, Mort must cluck, peck and comb-whip the pride of the farm back to safety.' FROM games WHERE igdb_id = 45049 ON CONFLICT (game_id, language_code) DO NOTHING;
