INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Phix: The Adventure', 'The Magnia Stone, the sacred stone of the Magnetic World is knocked off its floating altar in the sky and falls towards a slumbering creature called Phix. He swallows it and starts to attract metallic objects and creatures. This upsets the balance of the world, and evil creatures start to appear throughout the land. Phix must travel to five realms in order to bring the stone to its original place and return peace.' FROM games WHERE igdb_id = 46086 ON CONFLICT (game_id, language_code) DO NOTHING;
