INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Madden NFL 2001', 'Madden NFL 2001 includes several customizable modes. Players have the ability to create a play, create a player, run a franchise, and collect Madden Cards, allowing players to perform certain actions during gameplay (for example, adding 5th downs, or limiting the CPU-controlled team to 3rd downs). The cards can also alter individual player ratings, unlock special stadiums, and unlock Hall of Fame and All-Madden teams.' FROM games WHERE igdb_id = 3538 ON CONFLICT (game_id, language_code) DO NOTHING;
