INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sammy Sosa Softball Slam', 'Sammy Sosa Softball Slam brings the ultra-popular game of softball to the PlayStation game console for the first time ever for an entirely new game experience!  Step up to the plate for more fast-paced game play as you knock out doubles and triples. All this over-the-top action comes screaming at you through a non-stop barrage of instant camera cuts combined with sizzling special effects, side-splitting animations and a bombastic announcer guaranteed to keep you on your toes and wanting more!' FROM games WHERE igdb_id = 45051 ON CONFLICT (game_id, language_code) DO NOTHING;
