INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kikou Seiki Unitron', 'The game takes place 400 years after Biomotor Unitron. Kikou Seiki Unitron plays similar to Biomotor Unitron with top down dungeons and menu-based combat. The game requires the player to upgrade their unitron robot with various weapons and accessories to compete against various enemies within the dungeon areas. Using a link cable two players can pit their unitrons against each other in a head-to-head battle.' FROM games WHERE igdb_id = 43969 ON CONFLICT (game_id, language_code) DO NOTHING;
