INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Silent Scope', 'Silent Scope is an arcade game that puts the player in the shoes of a sniper during a series of terrorist incidents. The game uses a rifle that is mounted on the console, requiring players to physically alter their position in order to shoot accurately. In addition, the rifle''s scope displays a close-up view of a small portion of the screen, representing the sniper''s long-range view of the area where the rifle is pointed.' FROM games WHERE igdb_id = 49182 ON CONFLICT (game_id, language_code) DO NOTHING;
