INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sentimental Graffiti 2', 'The second game takes place in a world in which the first protagonist died in a traffic accident during his journey. The game takes place in a college town in which the original 12 girls have gathered to attend. The protagonist, Shiina Kouhei, is a second-year college student and a member of the Photography Club. He has been tasked with the job of finding his own model for the photo exhibition at the upcoming school festival, and thus turns to one of the now emotionally scarred girls in hopes of convincing them to become his model.' FROM games WHERE igdb_id = 130632 ON CONFLICT (game_id, language_code) DO NOTHING;
