INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Who Wants to Be a Millionaire: Sports Edition', 'The TV show of 2000 continues with this PC title, dedicated to Sports. There are 700 sports related questions in all, with the famous three lifelines available to use (Ask the Audience, Phone a Friend and 50/50). Add to that Regis Philbin pushing you along to your quest of a (fake) million in cash. It''s the closest you''ll get to the real thing. Regis that is.' FROM games WHERE igdb_id = 51331 ON CONFLICT (game_id, language_code) DO NOTHING;
