INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Family Game Pack', 'Family Game Pack features 25 classic games for you to play. It includes casino games such as 5 video poker variations ,slot machines, and Blackjack. Also included are board games which are Backgammon, Checkers, Chess, Dominoes, and Reversi. There are also card games including the games of Hearts, Spades, Crazy Eights, Go Fish, and Old Maid. Solitaire games of Klondike, Auld Lang Syne, Calculation, Scorpion, & Flower Garden also make an appearance.' FROM games WHERE igdb_id = 131184 ON CONFLICT (game_id, language_code) DO NOTHING;
