INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mickey Mouse Kindergarten', 'Disney Learning Mickey introduces school-age players to the worlds of time, listening, and dancing. Players will have the company of Mickey Mouse, Donald Duck, and other Disney characters throughout the game. The "edutainment" includes matching exercises, identification games, and creativity art opportunities. The developers have targeted seven primary areas: cognitive, creative, emotional, moral, physical, social, and thinking skills are all given attention.' FROM games WHERE igdb_id = 208723 ON CONFLICT (game_id, language_code) DO NOTHING;
