INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dead or Alive 2: Hardcore', 'Dead or Alive 2:Harcore is a fighting game in the Dead or Alive series, developed by Team Ninja and published by Tecmo. It debuted in arcades in 1999 and was later ported for the Dreamcast and the PlayStation 2 in 2000. Several enhanced editions of the game were released, including the updates Dead or Alive 2 Hardcore and Dead or Alive 2 HardCore.' FROM games WHERE igdb_id = 77986 ON CONFLICT (game_id, language_code) DO NOTHING;
