INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Clusterball', 'What is Clusterball? It''s a sport. Clusterball is an online sport, designed to invoke the same adrenaline rush as Quake and Unreal, but replacing the spatter and gore with pure gameplay. By combining the feel and gaming experience from ball, flight and racing games, Clusterball is totally unlike anything you?ve ever seen before.' FROM games WHERE igdb_id = 10349 ON CONFLICT (game_id, language_code) DO NOTHING;
