INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Theocracy', 'Theocracy is a real-time strategy game for the PC developed by Philos Laboratories and published by Ubisoft in 2000. The game takes place in Mexico and Central America in the 15th century. The player controls a tribe in this region, and has 100 years to prepare for a Spanish invasion by expanding their territory across the Central American map, by conquest, or by allying and trading with other tribes.' FROM games WHERE igdb_id = 6028 ON CONFLICT (game_id, language_code) DO NOTHING;
