INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marvin Strikes Back!', 'Looney Tunes: Marvin Strikes Back! (Looney Tunes Collector: Martian Revenge in Europe) is a Looney Tunes game published by Infogrames for the Game Boy Color in 2000. It is both a direct and spiritual sequel to "Looney Tunes Collector: Alert!", as both share near-identical gameplay. Its name could be a reference to Star Wars Episode V: The Empire Strikes Back.' FROM games WHERE igdb_id = 49854 ON CONFLICT (game_id, language_code) DO NOTHING;
