INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('qix-adventure', 49997, '2000-11-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6it8.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Qix Adventure', 'Can you trap the elusive line of energy that''s bouncing all around? Based on the coin-operated classic, QIX, this GBC sequel to the puzzle-based original offers similar gaming styles and a few welcome updates. In this take, you''ll use a cursor to draw boxes on the screen, avoiding the Qix. If you can draw a compete box without the Qix touching its perimeter, that area of the screen will disappear and get you one step closer to advancing. Adding an element of story, QIX ADVENTURE casts you in the role of Speedy, a treasure hunter who''s traveled to a mysterious island. Each level that you pass will help you in your quest to rid the island of all its strange creatures. Easy to learn but extremely difficult to master, QIX ADVENTURE is addicting fun for puzzle lovers and other gamers. Are you quick enough for Qix? Find out alone or against a friend.' FROM games WHERE igdb_id = 49997 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 49997 AND ge.slug = 'puzzle' ON CONFLICT DO NOTHING;
