INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dynamite Slugger', 'Dynamite Slugger is a video game. It was released in 2000 for the Neo Geo Pocket Color handheld game console. The game is similar to other Baseball videogames on the Neo Geo Pocket Color such as Baseball Stars and Baseball Stars Color. Due to Dynamite Slugger being the latest baseball videogame to be released for the Neo Geo Pocket Color it features better graphics than other sports titles.' FROM games WHERE igdb_id = 43999 ON CONFLICT (game_id, language_code) DO NOTHING;
