INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Xuan-Yuan Sword 3: The Scar of the Sky', 'The Magic System is revamped in this game. All magics now belong to one of the five elements of metal, wood, water, fire, and earth in Chinese mythology. The game was released on December 2, 2000. A television series based from the game, produced by Chinese Entertainment Shanghai Limited, starring Hu Ge and Cecilia Liu, aired in 2012.' FROM games WHERE igdb_id = 106678 ON CONFLICT (game_id, language_code) DO NOTHING;
