INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Max and the Haunted Castle', 'Max and the Haunted Castle is a point-and-click game for kids, starring the friendly dog Max who lives in a small village. One day, he hears dire news: Willy, a friendly ghost living in a haunted castle, is stuck in a room and is too hungry to escape via his ghostly powers. The only way to free Willy is to find enough of his favorite food, i.e. holey yellow socks. Max sets out to the castle to free the unfortunate ghost.' FROM games WHERE igdb_id = 127150 ON CONFLICT (game_id, language_code) DO NOTHING;
