INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Boku no Natsuyasumi', 'The game revolves around Boku, a 9 year old boy sent to his aunt and uncle in Japan''s wooded countryside and the daily adventures he encounters there. Boku is there because his Mother is in her final month of pregnancy. The player controls him for the 31 days of August 1975 (In Japan, a Summer Vacation, called natsuyasumi last for one month). You explore the game''s area and can catch bugs and pit them against each other, collect bottle caps, fly a kite, or just relax.' FROM games WHERE igdb_id = 44775 ON CONFLICT (game_id, language_code) DO NOTHING;
