INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vegas Games 2000', 'Vegas Games 2000 is a collection of casino games. The game claims twenty five games but this total is achieved by having multiple versions of some games. The package contains: - Baccarat - Big Spin Money Wheel - Blackjack: One, Two, Four or Six decks - Craps - Keno - Poker: 5 Card Draw, 5 Card Stud, 7 Card Stud, Texas Hold ''Em, Jacks or Better - Roulette - Slot Machines: Beyond the Stars, Easy Money, Love 2 Win, Buffet and Ancient - Treasures - Video Keno - Video Poker: Tens or better, Jacks or better double down, Jacks or better high roller, Jokers Wild, Deuces Wild Many games can be played in multiple denominations and some, such as video poker, have a double down feature.' FROM games WHERE igdb_id = 46639 ON CONFLICT (game_id, language_code) DO NOTHING;
