INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('styrlitz-2-tango-in-pampas', 69744, '2000-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7kx9.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Styrlitz 2: Tango in Pampas', 'Styrlitz is a comedic point-and-click adventure game. It is a parody of the popular Soviet television series Seventeen Moments of Spring about the exploits of a Soviet spy operating in Nazi Germany under the name Max Otto von Stierlitz. This is a sequel to the 1999 game Styrlitz. In this entry in the series, Styrlitz goes to South America to retrieve the cap of Vladimir Lenin that was stolen from the Mausoleum. There he confronts the famous nazi criminal Martin Bormann.' FROM games WHERE igdb_id = 69744 ON CONFLICT (game_id, language_code) DO NOTHING;
