INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ojarumaru-mitsunegai-jinja-no-ennichi-de-ojaru', 282392, '2000-06-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7lyr.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ojarumaru: Mitsunegai Jinja no Ennichi de Ojaru!', 'Turn the fun of the festival into a mini game. If you get a high score in a mini game, you will get a Menko card. Collected Enco Cards can be used to play against friends or exchange Menco. The modes are "Kin-chan''s goldfish scooping", "Mike''s relaxing quoits", "Sachiyo Usui''s yo-yo fishing", "Tommy grandpa''s shooting", "Ken''s octopus grilling", "Haunted mansion captain''s haunted mansion", "Poverty god and twin dog mini" "Golf", "Cold Sai and Ko-chan''s fortune-telling", and "Menko card game" are available. Fortune-telling can be printed out with a pocket printer.' FROM games WHERE igdb_id = 282392 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 282392 AND p.igdb_id = 22 ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ojarumaru-tsukiyo-ga-ike-no-takaramono', 282393, '2000-07-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7lys.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ojarumaru: Tsukiyo ga Ike no Takaramono', 'A game of the popular NHK educational anime "Ojarumaru". There are 3 modes: "Tabi-dachi niru (single-player mode)", "Tokukun-itashimasu (mini-game mode)", and "Welcome to me (two-player battle mode)". Set in Moonlight Town, the game is played in a sugoroku format, collecting items placed in each square, playing against each other in a mini game, and more when one of them finishes at the pond. The one who collects the points of is the winner.' FROM games WHERE igdb_id = 282393 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 282393 AND p.igdb_id = 22 ON CONFLICT DO NOTHING;
