INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tantei Shinshi Dash!', 'Tantei Shinshi Dash! is an Adventure game. Thist visual novel starts you off in the room belonging to a down and out detective mulling over what a dull and sad life he has.' FROM games WHERE igdb_id = 122873 ON CONFLICT (game_id, language_code) DO NOTHING;
