INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Generation Girl Gotta Groove', 'A dancing game featuring the Generation Girl line of Barbie dolls. Generation Girl Gotta Groove is a creativity game that offers Barbie fans the opportunity to choose a character (Barbie, Marissa, Nichelle, Susie, Chelsie or Marie), dress her up, choose music and perform her own dances. Girls can train, print cards, and record up to 9 dance sessions. The program can also import pictures from the Barbie Photo Designer digital camera.' FROM games WHERE igdb_id = 65916 ON CONFLICT (game_id, language_code) DO NOTHING;
