INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Demolition Racer: No Exit', 'The sequel to Demolition Racer. Race 14 tortuous tracks with mines and crates all over the place slowing you down, racing over 16 savage cars to a sports car to a hearse with its own characteristics to win the race. New game mode "last man standing" where you face all cars in race not for position, but to wreck each other going down a track to see who''s last, and "demolition derby" where you fight cars in a arena to see who''s last by hitting each other with state-of-the-art graphics where you can see tires, doors, hoods, bumpers, etc. go everywhere.' FROM games WHERE igdb_id = 46376 ON CONFLICT (game_id, language_code) DO NOTHING;
