INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pompei: The Legend of Vesuvius', 'Pompei: The Legend of Vesuvius (aka TimeScape: Journey to Pompeii) is a 2000 historical adventure game. It followed by a sequel, Jerusalem: The Three Roads to the Holy Land. When an explorer and world famous cartographer by the name of Adrien Blake returns from an expedition he discovers that his fiancée, Sophia has disappeared. Wrought with grief Adrian immerses himself in his manuscripts and reveals an ancient curse placed on him by the goddess Ishtar. Blake must go to 79AD Pompei, where a volcano will erupt in four days time, destroying the city, and find Sophia.' FROM games WHERE igdb_id = 53465 ON CONFLICT (game_id, language_code) DO NOTHING;
