INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Catechumen', 'A Christian-themed first-person-shooter, you are a Christian-in-training in the Ancient Roman times. You are battling the hordes of demons sent by the devil to corrupt Roman souls. Most of your comrades have been locked away by the possessed Romans. Only you, armed with a holy sword that shoots word of God, can enlighten the possessed Centurions, banish the demons, save your fellow Christians, and defeat Satan himself...' FROM games WHERE igdb_id = 84468 ON CONFLICT (game_id, language_code) DO NOTHING;
