INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dance Dance Revolution 3rdMix Plus', 'Dance Dance Revolution 3rdMix Plus is a re-issue of 3rdMix released on June 21, 2000. This title, exclusive to Japan, does away with SSR mode and allows the player to select Maniac difficulty in 3rdMix mode. It also adds 23 songs: 14 brand-new songs, the seven new songs added to verKorea1, and two more carryovers from 2ndMix. With few songs from DDR Solo 2000.' FROM games WHERE igdb_id = 135384 ON CONFLICT (game_id, language_code) DO NOTHING;
