INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pinball!', 'This cancelled pinball game was originally developed in 1978 by Ralph Baer for the Odyssey 2. It allowed players to build their own tables by positioning O-shaped bumpers onscreen. Ralph Baer never completed it, but in 2000 he authorized the creation of 30 cartridges of the prototype, which were sold at Classic Gaming Expo 2000.' FROM games WHERE igdb_id = 116671 ON CONFLICT (game_id, language_code) DO NOTHING;
