INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hamster Club: Awasete Chu', 'A puzzle game. Work with the cute hamsters to get rid of the falling blocks. There are two modes: "single mode" where you can see the ending according to the score when you select a support character and increase the score, and "2P battle mode" where you lose if the blocks are piled up first. The first privilege is an original key chain gift.' FROM games WHERE igdb_id = 281541 ON CONFLICT (game_id, language_code) DO NOTHING;
