INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: Anakin''s Speedway', 'Star Wars: Anakin''s Speedway challenges kids to construct and master podracing test tracks with their favorite Episode I characters such as Anakin, Sebulba, and Gasgano. Players could create thousands of tracks filled with turns, loops, jumps, and tunnels while learning the dynamics of speed and momentum.' FROM games WHERE igdb_id = 73217 ON CONFLICT (game_id, language_code) DO NOTHING;
