INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('capn-crunchs-crunchling-adventure', 135737, '2000-06-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2cny.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8ewj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cap''n Crunch''s Crunchling Adventure', 'This game was released as a game to advertise Cap''n Crunch cereal. In the game you raise crunchlings by playing mini-games to raise their stats, in order to defeat the boss at the end. There are 3 separate mini-games in the game. In Winter 1999, the "Where''s the Cap''n?" promotion returned from 1985. This time kids could log on to the internet to help solve the clues regarding where he had disappeared to. In Spring 2000, the Cap''n was back. This time it was revealed he was in Volcanica (at the center of the Earth) saving the Earth''s supply of Crunchium. Alongside his return was this game packaged with specially marked boxes of cereal.' FROM games WHERE igdb_id = 135737 ON CONFLICT (game_id, language_code) DO NOTHING;
