INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nushi Tsuri Adventure: Kite no Bouken', 'Nushi Tsuri Adventure: Kite no Bouken is a Sports game, developed by TOSE and published by Victor Interactive Software, which was released in Japan in 2000. The series is a cross between Harvest Moon and Final Fantasy / Dragon Quest. The first game finds the protagonist setting off on a quest to find a legendary fish, said to cure a life threatening illness his sister is suffering from. But like any quest, there will be plenty of obstacles in true RPG style.' FROM games WHERE igdb_id = 50560 ON CONFLICT (game_id, language_code) DO NOTHING;
