INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('superlite-1500-series-sudoku-5', 216564, '2000-06-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co586b.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sciqwi.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SuperLite 1500 Series: Sudoku 5', 'Sudoku is a logic-based, combinatorial number-placement puzzle. The objective is to fill a 9×9 grid with digits so that each column, each row, and each of the nine 3×3 sub-grids that compose the grid (also called "boxes", "blocks", "regions", or "sub-squares") contains all of the digits from 1 to 9. The puzzle setter provides a partially completed grid, which typically has a unique solution. Completed puzzles are always a type of Latin square with an additional constraint on the contents of individual regions. For example, the same single integer may not appear twice in the same 9x9 playing board row or column or in any of the nine 3x3 subregions of the 9x9 playing board. The puzzle was popularized in 1986 by the Japanese puzzle company Nikoli, under the name Sudoku, meaning single number. It became an international hit in 2005. SuperLite 1500 Series - Suudoku 5 is the fifth sudoku game in the series for the Playstation One console that features over 200 different sudoku challenges. The game features 3 different difficulty levels (easy, medium & hard) each of them with several sudoku puzzles..' FROM games WHERE igdb_id = 216564 ON CONFLICT (game_id, language_code) DO NOTHING;
