INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pocket Sakura', 'Pocket Sakura is a Sakura Taisen-themed LCD digital pet developed by Jupiter and published by Media Factory, and released exclusively in Japan in June 2000. It tracks the wearer''s steps with a built-in pedometer and allows for connectivity with the Game Boy Color game Sakura Taisen GB: Geki Hanagumi Nyuutai! for unlocking bonus content in that game.' FROM games WHERE igdb_id = 198648 ON CONFLICT (game_id, language_code) DO NOTHING;
