INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Keyboardmania', 'Keyboardmania (alternately KEYBOARD MANIA, and abbreviated KBM) is a rhythm video game created by the Bemani division of Konami. In this game up to two players use 24-key keyboards to play the piano or keyboard part of a selected song. Notes are represented on-screen by small bars that scroll downward above an image of the keyboard itself. The goal is to play the matching key when a note bar descends to the red play point line. The arcade cabinet has two screens - one for each player.' FROM games WHERE igdb_id = 92705 ON CONFLICT (game_id, language_code) DO NOTHING;
