INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rollcage Stage II', 'Rollcage Stage II is an arcade-style racing game for PlayStation and PC, developed by Attention To Detail, and published by Psygnosis. It is the sequel to Rollcage and was released in 2000. On top of the basic racing concept, the cars can be equipped with weapons, that are picked up on the track as bonuses, which can be used against competing cars. The automobiles themselves, once again, have wheels that are larger than the body of the car thus creating a car that has no ''right way up'' and can be flipped and continue to drive.' FROM games WHERE igdb_id = 3163 ON CONFLICT (game_id, language_code) DO NOTHING;
