INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Army Men: Air Tactics', 'Take to the skies with this new addition to the Army Men series. This time you must take control of the latest air attack machines in the world of war, and bash the plastic out of the Tan forces before they do it to you!! Fly through the bathroom, clash in the sandbox or destroy the flower garden, the choice is yours. Plus four new ways to clash with your pals.' FROM games WHERE igdb_id = 73898 ON CONFLICT (game_id, language_code) DO NOTHING;
