INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sabrina-the-animated-series-zapped', 49943, '2000-12-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8dyv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scv2ta.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sabrina the Animated Series: Zapped!', 'Sabrina has messed up again: she has turned all of the kids into animals. Now, she must travel through town and change the kids back. In order to turn the kids back, she must hit them and then use her magic on them. There are a number of power-ups available to help Sabrina on her quest, including quadruple jumps, a butt stomp, and warping abilities. She can also collect five stars that will allow her to change the kids back without having to stun them first. However, there are areas in each stage that Sabrina cannot reach. So she must find Salem, who can crawl through small spaces and use his tail to knock over blocks to clear a path for Sabrina. Getting through a level will require planning and skill, so put on your thinking cap. Help Sabrina return her classmates to normal in SABRINA THE ANIMATED SERIES: Zapped!' FROM games WHERE igdb_id = 49943 ON CONFLICT (game_id, language_code) DO NOTHING;
