INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('turok-3-shadow-of-oblivion', 1328, '2000-08-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2zqo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar220i.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Turok 3: Shadow of Oblivion', 'Turok 3: Shadow of Oblivion picks up where Turok 2: Seeds of Evil left off. Oblivion, a monstrous cosmic entity that consumed everything in its path and reigned before the birth of our universe is now invading the bodies of the living and devouring them from the inside-out. When the Primagen''s Lightship was destroyed, the chain reaction it triggered as a result was so powerful that the universe as it existed was completely eradicated, and the almighty Oblivion was pushed to the very brink of destruction. For the first time, Oblivion felt pain, fear, and hate. Oblivion survived and now desperately seeks a means to punch through the Netherscape that separates our world from the Lost Lands. The last shreds of the pure energy source that created our world and nearly wiped out Oblivion are contained within the Light Burden, the bag that every member of the Turok lineage has carried. Unless Danielle and Joseph Fireseed, siblings that carry the title of Turok, can stop the death of the Turok mantle, it will signal the beginning of the end - the rebirth of Oblivion.' FROM games WHERE igdb_id = 1328 ON CONFLICT (game_id, language_code) DO NOTHING;
