INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('trick-boarder', 49989, '2000-07-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/d8p6wtwajym3ulngyuxc.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trick Boarder', 'Send yourself speeding down a hill to claim first place in TRICK BOARDER. Choose from eight snowboarders, each with different attributes. Learn how to navigate all nine tracks and set speed records in the Time Trial mode. When you want to compete, try to claim the championship in the Grand Prix mode, where you earn points by finishing well on all nine tracks. If you have friends that are into snowboarding, you can challenge them to a race via the link cable. No matter what mode you play, you must keep an eye out for obstacles, or you will lose precious speed and time. Luckily, you can pick up icons that will give you turbo boosts, and you can perform tricks or go through slalom gates that will award additional speed boosts as well. Work your way through the ranks to become a snowboarding champion in TRICK BOARDER.' FROM games WHERE igdb_id = 49989 ON CONFLICT (game_id, language_code) DO NOTHING;
