INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Choro Q 64 2: Hacha-mecha Grand Prix Race', 'Choro Q 64 2: Hacha-mecha Grand Prix Race is a racing game released in 1999 in Japan for the Nintendo 64. It is the sequel to Choro Q 64 (Penny Racers outside of Japan) and is part of the Choro Q series. The game is also compatible with the Game Boy Color game Choro Q Hyper Customable GB, using the GB Transfer Pak.' FROM games WHERE igdb_id = 47742 ON CONFLICT (game_id, language_code) DO NOTHING;
