INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bygg Flygplan med Mulle Meck', 'The player gets to know that Mulle Meck has found the abandoned hangar of two air planes constructors and wants to try that trade. Again he receives his parts from Doris Digital. Gary flies to visit his friends and like in the previous episodes he gets orders which the player must complete.' FROM games WHERE igdb_id = 97735 ON CONFLICT (game_id, language_code) DO NOTHING;
