INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'G-Sector', 'G-Sector is a 3D action game based around hoverboard combat--a hybrid of an extreme game and a third-person shooter. Players control the heroine, Cyra, as she hoverboards through futuristic cities and arenas. Gameplay is based on ramps and tricks you use to build velocity and avoid opponents'' shots. Using a chase-cam and a customizable mouse/keyboard interface, G-Sector should be familiar to players of 3D shooters.' FROM games WHERE igdb_id = 306857 ON CONFLICT (game_id, language_code) DO NOTHING;
