INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Quadrax III', 'Quadrax III is a non-official Windows freeware remake of Quadrax, with new graphics and animations. The gameplay is the same - two characters have to be moved to a predefined place in logical levels, screen is filled with obstacles, the characters need to help each other get around by flipping switches, moving stone blocks, opening doors, and using lifts. The game has 45 levels, which are much harder than in the original game.' FROM games WHERE igdb_id = 69590 ON CONFLICT (game_id, language_code) DO NOTHING;
