INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yu-Gi-Oh! Dark Duel Stories', 'Yu-Gi-Oh! Dark Duel Stories, released in Japan as Yu-Gi-Oh! Duel Monsters III: Tri-Holy God Advent, is a Game Boy Color video game and the third title in the Yu-Gi-Oh! Duel Monsters series of games. It was released in Japan on July 13, 2000, and it was the first Yu-Gi-Oh! video game to be released outside of Japan, with a United States release date of March 19, 2002. Players of the game can trade and battle with other players using a link cable.' FROM games WHERE igdb_id = 23467 ON CONFLICT (game_id, language_code) DO NOTHING;
