INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brother 2: Back to America', 'This game based on a plot of the famous Russian blockbuster movie "Brother 2". Main character of the game is a young Russian boy named Danila. He learns that his brother is in the hands of the American mobsters and returns to America to help out his brother. As with any first-person shooter game, the player will going through various levels, killing enemies using firearms and cold steel. This game also has a few adventure elements. Daniel can pick up, use and combine different items, such as cutting pipes, nails, insulation tape, etc.' FROM games WHERE igdb_id = 122009 ON CONFLICT (game_id, language_code) DO NOTHING;
