INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 1500 Series Vol. 29: The Tsuri', 'Simple 1500 Series vol. 29 - The Tsuri is a first person perspective fishing game That features 5 different main fishing spots (with different part of each fishing spot for the player to choose where to fish) in places like rivers, ponds, etc. The game is about fishing freshwater fishes, there are 2 games modes: Free mode and challenge mode. The free mode is just choose a spot and go to fish there. In the challenge mode the game challenge the player to catch a fish with a specific weight.' FROM games WHERE igdb_id = 203014 ON CONFLICT (game_id, language_code) DO NOTHING;
