INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zeus: Master of Olympus', 'Zeus: Master of Olympus is the fifth full title of the City Building Series, developed by Impressions Games and published by Sierra Entertainment. Like previous titles, Zeus focuses on the building and development of a city in ancient times, this time in Ancient Greece. It features some changes to the Caesar III engine, most notably the new housing blocks, now dividing "common" and "elite" housing from the start, and more detailed walkers.' FROM games WHERE igdb_id = 958 ON CONFLICT (game_id, language_code) DO NOTHING;
