INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tee Off', 'One of the few golf games for the DC, with a cartoony style. Contains arcade mode, tournaments, five different courses and 15 characters (11 unlockable). Lots of different equipment (balls and clubs mostly) and even a futuristic cyber mini golf game are thrown in.' FROM games WHERE igdb_id = 46379 ON CONFLICT (game_id, language_code) DO NOTHING;
