INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'South Park Rally', 'Choose your character from the cast of the popular ''mature'' cartoon South Park, and tear through the streets in this racing game. Your character''s vehicle may be a little cart, trike, or box, for example. Weapons include rockets, Salty Balls, Cheesy Poofs, the beloved Cow and even an Anal probe. All of the voices are also included, making it feel more like the real cartoon than a rally game. You can also play an all-on-all 4 player mode.' FROM games WHERE igdb_id = 1259 ON CONFLICT (game_id, language_code) DO NOTHING;
