INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dance Dance Revolution: Disney Dancing Museum', 'The only Dance Dance Revolution release for the N64, DDR: DDM is intended for children to play. As always, your goal is to jump to the right arrows at the right time. When you are dancing, familiar Disney characters dance along in the background. Some of the songs are Disney-related, others are Japanese as this was a Japan-only release. The game requires the dance pad to play.' FROM games WHERE igdb_id = 3467 ON CONFLICT (game_id, language_code) DO NOTHING;
