INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('despiria', 92865, '2000-09-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co97je.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc94bc.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'deSpiria', 'deSpiria is an RPG adventure that takes place in the futuristic Japan of 2070. Twenty-two years after the World War III, an organization known as Church has taken power. You play as Allure Valentine, a girl who was recruited by the Church as an undercover agent. On one of her missions, Allure boards a train that crashes shortly thereafter. Her first task will be to find a way out of the underground tunnel and to discover who or what was behind that crash. The game is a RPG with elements of pure adventure. The entire game is viewed from first-person perspective. You fight enemies in turn-based battles, but instead of usual party you have several "minds", a kind of summoned monsters who will fight together with Allure. They will heal or attack the enemy using special "mind attacks" of various elements - love, curse, etc. In adventure mode, you explore the environments by pressing the A button, which will highlight objects you can interact with. The movements are shown as short CG sequences, similar to many Western-style adventures.' FROM games WHERE igdb_id = 92865 ON CONFLICT (game_id, language_code) DO NOTHING;
