INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jet de GO! Let''s Go By Airliner', 'Jet de GO! is a spin-off from the famous Densha de GO! series by Taito. Instead of trains, this title focus exclusively on flying planes. Players can take off and land with a Jetstream 31 turboprop, a mid-range Boeing 767 or a long haul Boeing 747. The game modes include Flight mode, Cruise mode and Lesson mode.' FROM games WHERE igdb_id = 61334 ON CONFLICT (game_id, language_code) DO NOTHING;
