INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kabobber', 40684, '2000-02-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co95ni.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scubjd.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kabobber', 'Kabobber was originally a prototype game that was programmed by Rex Bradford, known for his work on Star Wars: The Empire Strikes Back and Star Wars: Jedi Arena. It was discovered in 2000 and improved upon a little before being released to the public in ROM format. Kabobbers are strange (but cute) little creatures who just love wreaking havoc. Your objective is to send in your Buvskies to krush the Kabobbers before they krush you. You can have up to nine Buvskies onscreen at one time, but you have reserves waiting offscreen should one get krushed. You move your Bruvskies across the grid, jumping on enemy Kabobbers in order to defeat them and earn additional reserve Bruvskies. The baby Bruvskies become big ones when they defeat an enemy. The enemies get tougher and tougher, meaning very good timing is required in the later stages. Above all, you must reach Princess Buvsky before she reaches the rainbow energy at the other end of the level and devours it. A very unique game, but also somewhat fun.' FROM games WHERE igdb_id = 40684 ON CONFLICT (game_id, language_code) DO NOTHING;
