INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kiss-psycho-circus-the-nightmare-child', 9096, '2000-07-14', 90, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co40po.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7dxc.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kiss: Psycho Circus - The Nightmare Child', 'Wicked Jester, a band of four, are headed for a Friday night gig at The Coventry, a rundown dive outside of town. They arrive only to find the parking lot deserted, the club seemingly dead. The band''s members: Pablo Ramirez, Andy Chang, Gabriel Gordo and Patrick Scott, stepping from their van, are startled by a voice from the shadows. She offers them four tickets to a circus -- tonight''s the grand finale! Having nothing better to do, the four accept and the nightmare begins. Based on characters from comic book author Todd McFarlane, KISS Psycho Circus: The Nightmare Child brings the horror and carnage of the Psycho Circus to the PC in a shooter format. There are two-dozen creatures to battle with and three classes of weapons to use, each with four specific types: melee (beast claws, thornblade, twister and punisher), common (zero cannon, magma cannon, windblade and scourge) and ultimate (stargaze, galaxion, spirit lance and draco). In addition to the weaponry, temporary power-ups and instant items such as health, attack and defense powers are available.' FROM games WHERE igdb_id = 9096 ON CONFLICT (game_id, language_code) DO NOTHING;
