INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Enemy Engaged: Comanche vs Hokum', 'Enemy Engaged: Comanche vs Hokum is an attack helicopter simulation game. The game was a follow up to Enemy Engaged: Apache vs Havoc, and interconnectable with it. It was developed by Razorworks. Enemy Engaged 2 is its sequel.' FROM games WHERE igdb_id = 20374 ON CONFLICT (game_id, language_code) DO NOTHING;
