INSERT INTO game_screenshots (game_id, url, display_order, is_featured) SELECT id, 'https://images.igdb.com/igdb/image/upload/t_1080p/sc83c7.jpg', 7, false FROM games WHERE igdb_id = 1 ON CONFLICT DO NOTHING;
INSERT INTO game_screenshots (game_id, url, display_order, is_featured) SELECT id, 'https://images.igdb.com/igdb/image/upload/t_1080p/sc83c4.jpg', 8, false FROM games WHERE igdb_id = 1 ON CONFLICT DO NOTHING;
