INSERT INTO game_artwork (game_id, url, artwork_type, display_order, is_featured) SELECT id, 'https://images.igdb.com/igdb/image/upload/t_1080p/ar21mn.jpg', 'promotional', 0, true FROM games WHERE igdb_id = 1 ON CONFLICT DO NOTHING;
INSERT INTO game_videos (game_id, url, thumbnail_url, title, video_type, display_order, is_featured) SELECT id, 'https://www.youtube.com/watch?v=9C543B6uJ88', 'https://img.youtube.com/vi/9C543B6uJ88/maxresdefault.jpg', 'Trailer', 'trailer', 0, true FROM games WHERE igdb_id = 1 ON CONFLICT DO NOTHING;
INSERT INTO game_videos (game_id, url, thumbnail_url, title, video_type, display_order, is_featured) SELECT id, 'https://www.youtube.com/watch?v=rJchkcGRBrU', 'https://img.youtube.com/vi/rJchkcGRBrU/maxresdefault.jpg', 'Gameplay Video', 'trailer', 1, false FROM games WHERE igdb_id = 1 ON CONFLICT DO NOTHING;
INSERT INTO game_ratings (game_id, rating_id, is_primary) SELECT g.id, r.id, false FROM games g, ratings r JOIN rating_systems rs ON r.rating_system_id = rs.id WHERE g.igdb_id = 1 AND rs.code = 'CLASS_IND' AND r.code = '18' ON CONFLICT DO NOTHING;
INSERT INTO game_ratings (game_id, rating_id, is_primary) SELECT g.id, r.id, false FROM games g, ratings r JOIN rating_systems rs ON r.rating_system_id = rs.id WHERE g.igdb_id = 1 AND rs.code = 'PEGI' AND r.code = '16' ON CONFLICT DO NOTHING;
INSERT INTO game_ratings (game_id, rating_id, is_primary) SELECT g.id, r.id, false FROM games g, ratings r JOIN rating_systems rs ON r.rating_system_id = rs.id WHERE g.igdb_id = 1 AND rs.code = 'ESRB' AND r.code = 'M' ON CONFLICT DO NOTHING;
INSERT INTO game_ratings (game_id, rating_id, is_primary) SELECT g.id, r.id, false FROM games g, ratings r JOIN rating_systems rs ON r.rating_system_id = rs.id WHERE g.igdb_id = 1 AND rs.code = 'USK' AND r.code = '12' ON CONFLICT DO NOTHING;
INSERT INTO game_languages (game_id, language_code, language_name, has_audio, has_subtitles, has_interface) SELECT id, 'en', 'English', true, false, true FROM games WHERE igdb_id = 1 ON CONFLICT DO NOTHING;
INSERT INTO game_languages (game_id, language_code, language_name, has_audio, has_subtitles, has_interface) SELECT id, 'fr', 'French', true, false, true FROM games WHERE igdb_id = 1 ON CONFLICT DO NOTHING;
